// Visual explainers for the Kubernetes & Containers roadmap. Schema: CONTRIBUTING.md → "Visuals".
'use strict';

registerDiagram({
  id: 'k8s-apply-end-to-end',
  roadmap: 'kubernetes', module: 3, topic: 'What Happens on kubectl apply — End to End',
  kind: 'graph',
  title: 'kubectl apply → running Pod: who talks to whom',
  desc: 'Every component talks only to the API server, and each one reacts to changes it is watching. Press Play to follow a Deployment from kubectl to a running container.',
  groups: [
    { id: 'cp', label: 'Control plane', x: 1, y: 0, w: 3, h: 3, color: 'blue' },
    { id: 'wn', label: 'Worker node-1', x: 5, y: 0, w: 2, h: 3, color: 'green' },
  ],
  nodes: [
    { id: 'kubectl', label: 'kubectl', sub: 'you', icon: '🧑‍💻', x: 0, y: 1, color: 'gray', info: 'The CLI is just an HTTPS client of the API server. "apply" sends the manifest and a server-side merge computes what changed.' },
    { id: 'ctrl', label: 'controller-mgr', sub: 'reconcile loops', x: 1, y: 0, color: 'purple', info: 'kube-controller-manager runs reconcile loops. Each one watches a resource type and creates or deletes objects until actual state matches desired state.' },
    { id: 'api', label: 'kube-apiserver', sub: 'authn·authz·admit', x: 2, y: 1, color: 'blue', info: 'The only component that reads or writes etcd. Every request is authenticated, authorized (RBAC) and passed through admission (mutating, then validating) before it is stored.' },
    { id: 'sched', label: 'kube-scheduler', sub: 'filter→score→bind', x: 3, y: 0, color: 'orange', info: 'Watches for Pods with no spec.nodeName. It filters out nodes that cannot run the Pod (resources, taints, affinity), scores the rest and writes a Binding.' },
    { id: 'etcd', label: 'etcd', sub: 'cluster state', x: 2, y: 2, shape: 'db', color: 'teal', info: 'A consistent key-value store (Raft). It holds every API object. If etcd is lost without a backup, the cluster forgets everything it was told to run.' },
    { id: 'kubelet', label: 'kubelet', sub: 'node agent', x: 5, y: 1, color: 'green', info: 'Watches Pods bound to its node, asks the container runtime to run them, runs probes and reports status back to the API server.' },
    { id: 'cri', label: 'containerd', sub: 'CRI runtime + CNI', x: 5, y: 2, color: 'green', info: 'The container runtime. It pulls images and creates the pod sandbox; the CNI plugin gives the Pod its IP. runc starts the actual Linux processes.' },
    { id: 'pod', label: 'Pod', sub: 'containers running', icon: '📦', x: 6, y: 2, shape: 'pill', color: 'yellow', info: 'The smallest deployable unit: one or more containers that share a network namespace and volumes.' },
  ],
  edges: [
    { from: 'kubectl', to: 'api', label: 'HTTPS' },
    { from: 'api', to: 'etcd', both: true },
    { from: 'ctrl', to: 'api', both: true, label: 'watch' },
    { from: 'sched', to: 'api', both: true, label: 'watch' },
    { from: 'api', to: 'kubelet', both: true, label: 'watch Pods on node' },
    { from: 'kubelet', to: 'cri', label: 'CRI (gRPC)' },
    { from: 'cri', to: 'pod' },
  ],
  steps: [
    { caption: 'kubectl sends the Deployment manifest to kube-apiserver. The request is authenticated, authorized by RBAC and passed through admission webhooks before anything is stored.', flows: [{ from: 'kubectl', to: 'api', label: 'Deployment' }] },
    { caption: 'The API server persists the object in etcd and returns 201. That is all "apply" does: desired state is recorded, but nothing is running yet.', flows: [{ from: 'api', to: 'etcd', label: 'persist' }] },
    { caption: 'The Deployment controller sees the new Deployment through its watch and creates a ReplicaSet. The ReplicaSet controller then creates Pod objects. Each step is a write through the API server.', flows: [{ from: 'api', to: 'ctrl', label: 'event' }, { from: 'ctrl', to: 'api', label: 'create Pods' }] },
    { caption: 'The scheduler sees Pods with no node assigned. It filters and scores the nodes, then writes a Binding: "run this Pod on node-1".', flows: [{ from: 'api', to: 'sched', label: 'unscheduled' }, { from: 'sched', to: 'api', label: 'bind node-1' }] },
    { caption: 'The kubelet on node-1 is watching for Pods bound to its node, so it receives the new Pod spec.', flows: [{ from: 'api', to: 'kubelet', label: 'Pod spec' }] },
    { caption: 'The kubelet calls containerd over CRI: create the sandbox (CNI assigns an IP), pull the images and start the containers.', flows: [{ from: 'kubelet', to: 'cri', label: 'RunPodSandbox' }, { from: 'cri', to: 'pod', label: 'start' }] },
    { caption: 'The kubelet reports the Pod status back. Once the readiness probe passes, the Pod IP is added to the EndpointSlices and Services start sending it traffic.', flows: [{ from: 'kubelet', to: 'api', label: 'Running, Ready' }], active: ['pod'] },
  ],
});

// ===== Module 1: Virtualization vs Containerization =========================

registerDiagram({
  id: 'k8s-vm-vs-container',
  roadmap: 'kubernetes', module: 1, topic: 'Containers vs VMs',
  kind: 'graph',
  title: 'VM stack vs container stack: where the kernel lives',
  desc: 'Left: every VM boots its own kernel on virtual hardware. Right: containers are processes that share one host kernel and are fenced in by kernel features. Press Play to follow a syscall down each stack.',
  groups: [
    { id: 'vm1', label: 'VM 1', x: 0, y: 0, w: 1, h: 2, color: 'blue' },
    { id: 'vm2', label: 'VM 2', x: 1, y: 0, w: 1, h: 2, color: 'blue' },
    { id: 'c1', label: 'container A', x: 3, y: 0, w: 1, h: 1, color: 'green' },
    { id: 'c2', label: 'container B', x: 4, y: 0, w: 1, h: 1, color: 'green' },
  ],
  nodes: [
    { id: 'appA', label: 'App A', sub: '+ bins/libs', x: 0, y: 0, color: 'yellow', info: 'Your application plus the userland it needs, installed inside a full guest operating system.' },
    { id: 'appB', label: 'App B', sub: '+ bins/libs', x: 1, y: 0, color: 'yellow', info: 'A second VM can run a completely different OS (Windows next to Linux), because it has its own kernel.' },
    { id: 'gkA', label: 'Guest kernel', sub: 'full OS per VM', x: 0, y: 1, color: 'purple', info: 'Each VM boots its own kernel and init system. That costs hundreds of MB of RAM and seconds to minutes of boot time, but gives a hardware-level isolation boundary.' },
    { id: 'gkB', label: 'Guest kernel', sub: 'full OS per VM', x: 1, y: 1, color: 'purple', info: 'A kernel exploit inside VM 2 only compromises VM 2. To reach the host it must also break the hypervisor.' },
    { id: 'hyp', label: 'Hypervisor', sub: 'KVM · Hyper-V · ESXi · Xen', x: 0, y: 2, w: 2, color: 'orange', info: 'Type 1 hypervisors run on bare metal (ESXi, Xen, Hyper-V; KVM turns Linux into one). Type 2 run on a host OS (VirtualBox). Hardware virtualization (Intel VT-x, AMD-V, EPT) makes trapping cheap.' },
    { id: 'hwL', label: 'Hardware', sub: 'CPU with VT-x / AMD-V', x: 0, y: 3, w: 2, color: 'gray', info: 'Physical CPU, memory, disks and NICs, partitioned into virtual devices by the hypervisor.' },
    { id: 'cA', label: 'App A', sub: 'image userland only', x: 3, y: 0, color: 'yellow', info: 'The image contains only files: your binary, libraries, CA certificates. No kernel. A static Go binary on distroless or scratch can be a few MB.' },
    { id: 'cB', label: 'App B', sub: 'image userland only', x: 4, y: 0, color: 'yellow', info: 'Another process on the same host. It may use a different distro userland (Alpine vs Debian), but always the same host kernel.' },
    { id: 'iso', label: 'Kernel isolation', sub: 'namespaces · cgroups · seccomp · caps', x: 3, y: 1, w: 2, color: 'teal', info: 'Not a separate layer of software: these are features of the host kernel applied to the process. Namespaces control what it can see, cgroups what it can use, seccomp and capabilities what it may ask the kernel to do, and AppArmor/SELinux add mandatory access control.' },
    { id: 'hostk', label: 'Shared host kernel', sub: 'one kernel for every container', x: 3, y: 2, w: 2, color: 'blue', info: 'All containers share it: uname -r inside a container prints the host kernel and kernel modules are host-wide. Node-level sysctls (vm.*) are shared too, but namespaced ones (net.*, kernel.shm*, kernel.msg*, kernel.sem) are per Pod via securityContext.sysctls. Docker Desktop runs a hidden Linux VM.' },
    { id: 'hwR', label: 'Hardware', sub: 'bare metal or a cloud VM', x: 3, y: 3, w: 2, color: 'gray', info: 'In the cloud, Kubernetes nodes are usually VMs themselves, so you get both layers: VM isolation between tenants of the cloud, container isolation between your workloads.' },
  ],
  edges: [],
  steps: [
    { caption: 'A VM virtualizes hardware: the hypervisor hands each VM virtual CPUs, memory and devices, and every VM boots its own full guest kernel. That is why VM images are GBs and take seconds to minutes to boot.', active: ['vm1', 'vm2', 'gkA', 'gkB', 'hyp'] },
    { caption: 'A syscall in VM 1 is handled by its own guest kernel. Privileged operations trap to the hypervisor through hardware virtualization. The isolation boundary is the hypervisor: a small, well-audited attack surface.', flows: [{ from: 'appA', to: 'gkA', label: 'syscall' }, { from: 'gkA', to: 'hyp', label: 'trap (VM exit)' }] },
    { caption: 'A container is just a process. Its image ships only userland files; there is no guest kernel to boot, so it starts in milliseconds and adds almost no memory overhead. Density and fast startup are the win.', active: ['c1', 'c2', 'cA', 'cB'] },
    { caption: 'Its syscalls go straight to the shared host kernel. Namespaces limit what it can see (PIDs, mounts, network), cgroups limit what it can use (CPU, memory), seccomp and capabilities limit which syscalls it can make.', flows: [{ from: 'cA', to: 'iso', label: 'syscall' }, { from: 'iso', to: 'hostk', label: 'filtered view' }] },
    { caption: 'The trade-off: one shared kernel means one shared blast radius. A kernel exploit from container A escapes to the host and every other container on it. This is the answer to "are containers a security boundary?"', flows: [{ from: 'cA', to: 'iso', label: 'kernel exploit', color: 'red' }, { from: 'iso', to: 'hostk', label: 'host compromised', color: 'red' }], active: ['cB'] },
    { caption: 'Sandboxed runtimes combine both models: Kata Containers runs each Pod in a lightweight VM with its own kernel, gVisor intercepts syscalls in a user-space kernel. Select them per Pod with a RuntimeClass for untrusted code.', active: ['gkA', 'gkB', 'iso'] },
  ],
});

registerDiagram({
  id: 'k8s-runtime-stack',
  roadmap: 'kubernetes', module: 1, problem: 'Trace docker run / kubelet pod start through the runtime stack',
  kind: 'sequence',
  title: 'kubelet → containerd → shim → runc: starting a Pod',
  desc: 'The kubelet never starts processes itself. It calls the CRI API of containerd, which delegates networking to a CNI plugin and process creation to a shim and runc. Press Play to follow one Pod start.',
  actors: [
    { id: 'kl', label: 'kubelet', sub: 'node agent', icon: '🤖', color: 'blue', info: 'Calls the CRI gRPC API over a Unix socket (/run/containerd/containerd.sock). RuntimeService: RunPodSandbox, CreateContainer, StartContainer. ImageService: PullImage.' },
    { id: 'ctd', label: 'containerd', sub: 'built-in CRI plugin', color: 'green', info: 'High-level runtime: image pull and unpack (content store + snapshotters), OCI spec generation, container lifecycle. CRI-O is the Kubernetes-only alternative. Docker Engine also sits on top of containerd.' },
    { id: 'cni', label: 'CNI plugin', sub: 'Cilium, Calico, …', color: 'purple', info: 'A binary in /opt/cni/bin configured from /etc/cni/net.d. ADD creates the veth pair, assigns an IP from IPAM and sets routes; DEL cleans up.' },
    { id: 'shim', label: 'shim', sub: 'shim-runc-v2', color: 'orange', info: 'One shim per Pod sandbox. It is the parent of the container processes, keeps their stdio open and collects exit codes, so containerd can restart without killing containers.' },
    { id: 'runc', label: 'runc', sub: 'OCI runtime', color: 'red', info: 'Low-level OCI runtime (crun is a faster C alternative). Reads an OCI bundle (config.json + rootfs), creates namespaces and cgroups, applies seccomp, execs the process and exits. It is not a daemon.' },
  ],
  steps: [
    { section: 'RunPodSandbox: the shared Pod shell' },
    { from: 'kl', to: 'ctd', label: 'RunPodSandbox', caption: 'The kubelet asks for a sandbox: the set of namespaces (network, IPC, UTS) that all containers of the Pod will share. Nothing of your app runs yet.' },
    { from: 'ctd', to: 'cni', label: 'ADD (netns path)', caption: 'containerd creates a new network namespace and executes the CNI plugin with its path. The plugin creates a veth pair, assigns a Pod IP from IPAM and programs routes.' },
    { from: 'cni', to: 'ctd', label: 'IP 10.244.1.7', reply: true, caption: 'The CNI result (Pod IP, routes) goes back to containerd and later into the Pod status. If this step fails, the Pod is stuck in ContainerCreating with a "failed to set up sandbox" event.' },
    { from: 'ctd', to: 'shim', label: 'start shim + pause container', caption: 'containerd launches a shim for the sandbox and asks it to run the pause container, whose only job is to hold the namespaces open and reap zombies.' },
    { from: 'shim', to: 'runc', label: 'runc create pause', caption: 'runc joins the prepared network namespace, creates the rest, applies cgroups and starts pause. The Pod now exists with an IP, but no app containers.' },
    { from: 'ctd', to: 'kl', label: 'sandbox ID', reply: true, caption: 'The kubelet gets the sandbox ID back and moves on to the containers, init containers first, in order.' },
    { section: 'Each container: pull, create, start' },
    { from: 'kl', to: 'ctd', label: 'PullImage', caption: 'containerd resolves the tag to a manifest digest for this node\'s platform, downloads missing layers into the content store and unpacks them with the overlayfs snapshotter. Cached layers are skipped.' },
    { from: 'kl', to: 'ctd', label: 'CreateContainer', caption: 'containerd generates the OCI config.json from the Pod spec: command, env, mounts, user, capabilities, seccomp and cgroup limits from resources. It prepares a writable overlay rootfs on top of the image layers.' },
    { from: 'kl', to: 'ctd', label: 'StartContainer', caption: 'Start is a separate call so the kubelet controls ordering, for example init containers and native sidecars before the app.' },
    { from: 'ctd', to: 'shim', label: 'start task', caption: 'containerd hands the container to the same shim that owns the sandbox.' },
    { from: 'shim', to: 'runc', label: 'runc create + start', caption: 'The shim invokes runc with the OCI bundle.' },
    { from: 'runc', to: 'runc', label: 'setns, exec, exit', caption: 'runc joins the Pod\'s shared namespaces, creates a new mount and PID namespace, applies the cgroup and seccomp profile, execs your entrypoint as PID 1, then exits immediately.' },
    { from: 'shim', to: 'shim', label: 'reap, hold stdio', caption: 'The shim is now the parent: it streams stdout/stderr to the log files under /var/log/pods and records the exit code. Because containerd is not the parent, upgrading or restarting it does not kill running containers.' },
  ],
});

// ===== Module 2: Docker ======================================================

registerDiagram({
  id: 'k8s-image-layer-cache',
  roadmap: 'kubernetes', module: 2, topic: 'Images, Layers & the Build Cache',
  kind: 'graph',
  title: 'Layer cache: why instruction order decides build time',
  desc: 'Two Dockerfiles for the same Go service. Once one step misses the cache, every later step rebuilds. Press Play to edit main.go and watch which layers are reused.',
  groups: [
    { id: 'good', label: 'Cache-friendly order', x: 0, y: 0, w: 3, h: 5, color: 'green' },
    { id: 'bad', label: 'Cache-busting order', x: 4, y: 0, w: 3, h: 5, color: 'red' },
  ],
  nodes: [
    { id: 'g0', label: 'FROM golang:1.25 AS build', sub: 'base image layers, pulled once', x: 0.25, y: 0, w: 2.5, color: 'gray', info: 'Pin the base image by digest in production so a re-tagged upstream image cannot silently change (and bust) your build.' },
    { id: 'g1', label: 'COPY go.mod go.sum ./', sub: 'cache key: checksums of 2 files', x: 0.25, y: 1, w: 2.5, color: 'blue', info: 'For COPY and ADD the cache key includes the checksums of the copied files, not their timestamps. These two files change only when dependencies change.' },
    { id: 'g2', label: 'RUN go mod download', sub: 'slow: fetches every module', x: 0.25, y: 2, w: 2.5, color: 'orange', info: 'For RUN the key is the command text plus the parent layer. The builder never re-runs it to check whether the network result changed, which is also why apt-get update must share a RUN with apt-get install.' },
    { id: 'g3', label: 'COPY . .', sub: 'cache key: checksums of all source', x: 0.25, y: 3, w: 2.5, color: 'blue', info: 'Changes on almost every commit. Keep it as late as possible, and keep .git, build output and .env files out of the context with .dockerignore.' },
    { id: 'g4', label: 'RUN go build -o /out/app', sub: 'compile the binary', x: 0.25, y: 4, w: 2.5, color: 'orange', info: 'In a multi-stage build only /out/app is copied into a distroless or scratch final stage, so the toolchain and module cache never ship.' },
    { id: 'b0', label: 'FROM golang:1.25 AS build', sub: 'base image layers', x: 4.25, y: 0, w: 2.5, color: 'gray', info: 'Same base image: this layer is still a cache hit.' },
    { id: 'b1', label: 'COPY . .', sub: 'any file change is a miss here', x: 4.25, y: 1, w: 2.5, color: 'blue', info: 'Copies the whole context before the dependencies are downloaded, so a one-line code change invalidates this layer and everything below it.' },
    { id: 'b2', label: 'RUN go mod download', sub: 'rebuilt on every commit', x: 4.25, y: 2, w: 2.5, color: 'orange', info: 'The parent layer changed, so this layer cannot be reused even though go.mod did not change.' },
    { id: 'b3', label: 'RUN go build -o /out/app', sub: 'compile the binary', x: 4.25, y: 3, w: 2.5, color: 'orange', info: 'Rebuilt as well, as it must be.' },
  ],
  edges: [
    { from: 'g0', to: 'g1' }, { from: 'g1', to: 'g2' }, { from: 'g2', to: 'g3' }, { from: 'g3', to: 'g4' },
    { from: 'b0', to: 'b1' }, { from: 'b1', to: 'b2' }, { from: 'b2', to: 'b3' },
  ],
  steps: [
    { caption: 'Each RUN, COPY and ADD adds a layer on top of the previous one. A layer is reused only if its parent was reused and its key matches: the instruction text, plus file checksums for COPY and ADD. ENV, CMD and LABEL only change the config.', active: ['g0', 'g1', 'g2', 'g3', 'g4'] },
    { caption: 'First build: nothing is cached, so every step runs and its result is stored under its key. The module download dominates the build time.', flows: [{ from: 'g0', to: 'g1', label: 'miss' }, { from: 'g1', to: 'g2', label: 'miss' }, { from: 'g2', to: 'g3', label: 'miss' }, { from: 'g3', to: 'g4', label: 'miss' }] },
    { caption: 'You edit main.go. go.mod and go.sum are unchanged, so the first three steps are cache hits and the slow download is reused. Only COPY . . and go build run again: seconds instead of minutes.', active: ['g0', 'g1', 'g2'], flows: [{ from: 'g2', to: 'g3', label: 'first miss', color: 'orange' }, { from: 'g3', to: 'g4', label: 'rebuild', color: 'orange' }] },
    { caption: 'Same edit, wrong order: COPY . . comes before the download, its checksum changes, so every later step rebuilds, including go mod download. This is the classic "every commit re-downloads all dependencies" bug.', active: ['b0'], flows: [{ from: 'b1', to: 'b2', label: 'miss', color: 'red' }, { from: 'b2', to: 'b3', label: 'miss', color: 'red' }] },
    { caption: 'Adding a dependency changes go.mod, so the good order misses at step 2 and re-downloads, which is correct. A BuildKit cache mount (RUN --mount=type=cache,target=/go/pkg/mod) keeps the module cache even when the layer misses.', flows: [{ from: 'g1', to: 'g2', label: 'miss', color: 'orange' }, { from: 'g2', to: 'g3', label: 'miss', color: 'orange' }, { from: 'g3', to: 'g4', label: 'miss', color: 'orange' }] },
    { caption: 'Without a .dockerignore, a change in .git or a local build artifact alters the checksum of COPY . . and busts the cache for no reason, and local .env files or keys can end up baked into a layer.', active: ['g3', 'b1'] },
  ],
});

registerDiagram({
  id: 'k8s-docker-bridge',
  roadmap: 'kubernetes', module: 2, topic: 'Container Networking',
  kind: 'graph',
  title: 'Docker bridge networking: veth, embedded DNS and NAT',
  desc: 'Two containers on a user-defined bridge network. Press Play to follow name resolution, container-to-container traffic, egress through MASQUERADE and an inbound published port through DNAT.',
  groups: [
    { id: 'host', label: 'Docker host (root network namespace)', x: 0, y: 0, w: 5, h: 5, color: 'gray' },
    { id: 'nsA', label: 'netns api', x: 1, y: 1, w: 1, h: 1, color: 'green' },
    { id: 'nsB', label: 'netns db', x: 3, y: 1, w: 1, h: 1, color: 'green' },
  ],
  nodes: [
    { id: 'dns', label: 'Embedded DNS', sub: '127.0.0.11 (dockerd)', x: 2, y: 0, color: 'purple', info: 'On user-defined networks Docker answers container and Compose service names. The legacy default bridge (docker0) has no name resolution: the old --link era.' },
    { id: 'ctrA', label: 'api container', sub: 'eth0 172.18.0.2', x: 1, y: 1, color: 'green', info: 'Its own network namespace: own interfaces, routes, iptables and port space. localhost here means this container only, so the app must listen on 0.0.0.0 to be reachable.' },
    { id: 'ctrB', label: 'db container', sub: 'eth0 172.18.0.3', x: 3, y: 1, color: 'green', info: 'Postgres listening on 5432. Other containers on the same network reach it at db:5432 without publishing any port.' },
    { id: 'bridge', label: 'br-app (Linux bridge)', sub: 'virtual switch · gateway 172.18.0.1', x: 1, y: 3, w: 3, color: 'blue', info: 'A software L2 switch in the host. Each container\'s veth peer is attached to it. The bridge IP is the containers\' default gateway.' },
    { id: 'nat', label: 'iptables NAT', sub: 'DNAT · MASQUERADE', x: 2, y: 4, color: 'orange', info: 'Docker installs nat rules: MASQUERADE for egress from the bridge subnet and DNAT for every published port. conntrack tracks each flow so replies are translated back. Your own filter rules belong in the DOCKER-USER chain.' },
    { id: 'heth', label: 'host eth0', sub: '192.168.1.10', x: 4, y: 4, color: 'gray', info: 'The host\'s real interface. All container egress leaves with this source IP.' },
    { id: 'net', label: 'LAN / Internet', sub: 'clients, registries', icon: '🌐', x: 6, y: 4, color: 'gray', info: 'Anything outside the host. It never sees 172.18.x.x addresses.' },
  ],
  edges: [
    { from: 'ctrA', to: 'bridge', label: 'veth pair' },
    { from: 'ctrB', to: 'bridge', label: 'veth pair' },
    { from: 'ctrA', to: 'dns' },
    { from: 'bridge', to: 'nat' },
    { from: 'nat', to: 'heth' },
    { from: 'heth', to: 'net' },
  ],
  steps: [
    { caption: 'Each container gets its own network namespace. Docker creates a veth pair per container: one end becomes eth0 inside the namespace, the other is plugged into the network\'s Linux bridge, a virtual switch.', active: ['ctrA', 'ctrB', 'bridge', 'ctrA>bridge', 'ctrB>bridge'] },
    { caption: 'On a user-defined network, the api container resolves "db" through Docker\'s embedded DNS at 127.0.0.11. On the default bridge this lookup fails: the classic "containers cannot reach each other by name" bug.', flows: [{ from: 'ctrA', to: 'dns', label: 'A? db' }, { from: 'dns', to: 'ctrA', label: '172.18.0.3' }] },
    { caption: 'Container to container on the same bridge is plain L2 switching: no NAT and no published ports. Use the container port (5432), not a host port. Containers on different networks cannot talk unless connected to both.', flows: [{ from: 'ctrA', to: 'bridge', label: '→ 172.18.0.3:5432' }, { from: 'bridge', to: 'ctrB', label: 'switched' }] },
    { caption: 'Egress: the packet goes to the bridge gateway, the host routes it (ip_forward) and MASQUERADE rewrites the source to the host IP. conntrack remembers the mapping so replies find their way back.', flows: [{ from: 'ctrA', to: 'bridge', label: '→ 140.82.1.1' }, { from: 'bridge', to: 'nat', label: 'route' }, { from: 'nat', to: 'heth', label: 'SNAT host IP' }, { from: 'heth', to: 'net', label: 'egress' }] },
    { caption: '-p 8080:80 adds a DNAT rule: host port 8080 → 172.18.0.2:80. EXPOSE publishes nothing; it is documentation. The app must listen on 0.0.0.0 inside the container, because 127.0.0.1 is the container itself.', flows: [{ from: 'net', to: 'heth', label: 'TCP :8080' }, { from: 'heth', to: 'nat', label: 'match rule' }, { from: 'nat', to: 'bridge', label: 'DNAT → :80' }, { from: 'bridge', to: 'ctrA', label: 'deliver' }] },
    { caption: 'Published ports bind 0.0.0.0 by default and Docker\'s rules run before ufw or firewalld chains, so the port is open to the network even if your host firewall says otherwise. Use -p 127.0.0.1:8080:80 for local-only services.', active: ['nat', 'heth', 'net'] },
  ],
});

// ===== Module 3: Kubernetes Architecture =====================================

registerDiagram({
  id: 'k8s-reconcile-loop',
  roadmap: 'kubernetes', module: 3, topic: 'Declarative Desired State & Reconciliation Loops',
  kind: 'graph',
  title: 'Inside a controller: informer, work queue, Reconcile',
  desc: 'Every Kubernetes controller (and every operator you write with controller-runtime) has the same anatomy. Press Play to delete a Pod and watch the ReplicaSet controller converge back to 3 replicas.',
  groups: [
    { id: 'ctrl', label: 'ReplicaSet controller (kube-controller-manager)', x: 2, y: 0, w: 3, h: 3, color: 'purple' },
  ],
  nodes: [
    { id: 'user', label: 'kubectl', sub: 'or a node failure', icon: '🧑‍💻', x: 0, y: 0, color: 'gray', info: 'Anything that changes actual state: a human, a crashed node, the eviction manager.' },
    { id: 'api', label: 'kube-apiserver', sub: 'desired + actual', x: 0, y: 2, color: 'blue', info: 'Holds spec (desired) and status (observed). Every write carries a resourceVersion: a stale update gets 409 Conflict and the controller re-reads and retries (optimistic concurrency).' },
    { id: 'etcd', label: 'etcd', sub: 'source of truth', x: 0, y: 3, shape: 'db', color: 'teal', info: 'Stores every object. resourceVersion is derived from the etcd revision, which is what lets a WATCH resume exactly where a LIST left off.' },
    { id: 'informer', label: 'Informer', sub: 'LIST, then WATCH', x: 2, y: 0, color: 'purple', info: 'client-go SharedInformer: an initial LIST, then a long-lived WATCH from that resourceVersion. On a dropped watch it re-lists. Event handlers enqueue keys, never full objects.' },
    { id: 'queue', label: 'Work queue', sub: 'dedup + rate limit', x: 4, y: 0, color: 'orange', info: 'Holds namespace/name keys. The same key queued 10 times is processed once, a key is never handled by two workers at once, and failures are retried with exponential backoff.' },
    { id: 'cache', label: 'Local cache', sub: 'indexed store', x: 2, y: 2, shape: 'db', color: 'purple', info: 'An in-memory copy of every watched object (Pods, ReplicaSets). Reconcile reads from here, so reads cost nothing on the API server. The cache can be slightly stale; optimistic concurrency catches that on write.' },
    { id: 'worker', label: 'Reconcile(key)', sub: 'desired vs actual', x: 4, y: 2, color: 'purple', info: 'Idempotent: it looks at the whole current state for one key and acts on the difference, never on "what the event said". Running it twice in a row does nothing the second time.' },
  ],
  edges: [
    { from: 'user', to: 'api', label: 'change' },
    { from: 'api', to: 'etcd', both: true },
    { from: 'api', to: 'informer', label: 'LIST, then WATCH' },
    { from: 'informer', to: 'cache', label: 'update store' },
    { from: 'informer', to: 'queue', label: 'enqueue key' },
    { from: 'queue', to: 'worker', label: 'pop key' },
    { from: 'worker', to: 'cache', label: 'read' },
    { from: 'worker', to: 'api', label: 'create Pod / status', curve: -80 },
  ],
  steps: [
    { caption: 'Desired state: ReplicaSet web, spec.replicas 3. At startup the informer LISTs Pods and ReplicaSets, fills its cache, then WATCHes from that resourceVersion so no change is missed between the two.', flows: [{ from: 'api', to: 'informer', label: 'LIST + WATCH' }, { from: 'informer', to: 'cache', label: 'fill cache' }] },
    { caption: 'Actual state drifts: someone deletes one of the 3 Pods (or its node dies). The API server records it like any other write.', flows: [{ from: 'user', to: 'api', label: 'delete web-x' }, { from: 'api', to: 'etcd', label: 'persist' }] },
    { caption: 'The watch delivers a DELETED event. The informer updates the cache and enqueues the key of the owning ReplicaSet, prod/web, found through the Pod\'s ownerReference. The key, not the event, is what gets queued.', flows: [{ from: 'api', to: 'informer', label: 'DELETED web-x' }, { from: 'informer', to: 'queue', label: 'prod/web' }] },
    { caption: 'A worker pops prod/web. If 50 Pods had changed at once, the key would still be processed once: the queue deduplicates, which keeps controllers cheap under bursts.', flows: [{ from: 'queue', to: 'worker', label: 'prod/web' }] },
    { caption: 'Reconcile compares desired (replicas 3) with actual (2 Pods matching the selector), reading both from the local cache with no API call.', flows: [{ from: 'worker', to: 'cache', label: 'list Pods' }, { from: 'cache', to: 'worker', label: '2 of 3' }] },
    { caption: 'It acts on the difference: creates 1 Pod with an ownerReference, then updates status.replicas and observedGeneration. If the write hits a 409 Conflict, the key is requeued with backoff and reconciled again from fresh state.', flows: [{ from: 'worker', to: 'api', label: 'create 1 Pod' }] },
    { caption: 'Level-triggered, not edge-triggered: if the controller had been down during the delete, on restart it simply re-LISTs, sees 2 of 3 and does the same thing. No event needs to be delivered exactly once.', flows: [{ from: 'api', to: 'informer', label: 're-LIST' }], active: ['worker'] },
  ],
});

// ===== Module 4: Workloads ===================================================

registerDiagram({
  id: 'k8s-pod-lifecycle',
  roadmap: 'kubernetes', module: 4, topic: 'Pods & the Pod Lifecycle',
  kind: 'graph',
  title: 'Pod phases vs container states',
  desc: 'A Pod has only five phases. The statuses you see in kubectl get pods, such as ImagePullBackOff and CrashLoopBackOff, are container waiting reasons inside a phase. Press Play to walk through the transitions.',
  groups: [
    { id: 'gp', label: 'phase Pending', x: 2, y: 1, w: 1, h: 3, color: 'yellow' },
    { id: 'gr', label: 'phase Running', x: 4, y: 1, w: 1, h: 3, color: 'green' },
  ],
  nodes: [
    { id: 'created', label: 'Pod object', sub: 'accepted by the API', x: 0, y: 1, shape: 'pill', color: 'gray', info: 'Created by a controller (ReplicaSet, Job, StatefulSet) far more often than by hand. Bare Pods are not recreated when their node dies.' },
    { id: 'pending', label: 'Pending', sub: 'scheduling, pulling', x: 2, y: 1, color: 'yellow', info: 'Accepted but not all containers are running yet: waiting for the scheduler (condition PodScheduled), for the sandbox and IP, for image pulls and for init containers to finish.' },
    { id: 'imgpull', label: 'ImagePullBackOff', sub: 'phase still Pending', x: 2, y: 3, color: 'red', info: 'Container state Waiting with reason ErrImagePull, then ImagePullBackOff while the kubelet retries with exponential backoff (up to 5 minutes). Read the exact error in the events.' },
    { id: 'running', label: 'Running', sub: '≥1 container running', x: 4, y: 1, color: 'green', info: 'Bound to a node and at least one container is running or restarting. Running is not Ready: Service traffic arrives only when the Ready condition is true (all containers pass readiness).' },
    { id: 'crash', label: 'CrashLoopBackOff', sub: 'phase still Running', x: 4, y: 3, color: 'red', info: 'A container keeps exiting and the kubelet waits 10 s, 20 s, 40 s … up to 5 min between restarts. The backoff resets after the container runs fine for 10 minutes. kubectl logs --previous shows the last crash.' },
    { id: 'succeeded', label: 'Succeeded', sub: 'all exited 0', x: 6, y: 0, color: 'teal', info: 'Terminal. Only reachable with restartPolicy Never or OnFailure (Jobs). With Always, an exited container is restarted instead.' },
    { id: 'unknown', label: 'Unknown', sub: 'node unreachable', x: 6, y: 1, color: 'gray', info: 'The control plane cannot get the Pod state because the kubelet stopped reporting. The node gets the unreachable taint and, after the default 300 s toleration, the Pod is evicted and replaced elsewhere.' },
    { id: 'failed', label: 'Failed', sub: 'a container failed', x: 6, y: 2, color: 'red', info: 'Terminal: all containers have terminated and at least one failed and will not be restarted. Pods evicted for node pressure also end up Failed with reason Evicted.' },
  ],
  edges: [
    { from: 'created', to: 'pending' },
    { from: 'pending', to: 'running', label: 'bound, started' },
    { from: 'pending', to: 'imgpull', both: true, label: 'pull error / retry' },
    { from: 'running', to: 'crash', both: true, label: 'exit → back-off' },
    { from: 'running', to: 'succeeded', label: 'all exit 0' },
    { from: 'running', to: 'unknown', label: 'kubelet silent' },
    { from: 'running', to: 'failed', label: 'exit ≠ 0, no restart' },
  ],
  steps: [
    { caption: 'The Pod is stored and its phase is Pending. Pending covers everything before the containers run: waiting for the scheduler, creating the sandbox and IP, pulling images and running init containers in order.', flows: [{ from: 'created', to: 'pending', label: 'created' }] },
    { caption: 'If the image cannot be pulled, the container is Waiting with reason ErrImagePull, then ImagePullBackOff. The phase stays Pending and the kubelet keeps retrying with backoff. kubectl describe shows the exact registry error.', flows: [{ from: 'pending', to: 'imgpull', label: 'pull fails', color: 'red' }] },
    { caption: 'Once the Pod is bound and at least one container is started, the phase becomes Running. Running is not Ready: only when readiness passes does the Pod join the EndpointSlices and receive Service traffic.', flows: [{ from: 'pending', to: 'running', label: 'started' }] },
    { caption: 'A container exits and restartPolicy Always restarts it with growing delays (10 s → 5 min cap). kubectl shows CrashLoopBackOff, yet the phase is still Running. Check logs --previous and the exit code: 137 is SIGKILL (OOM or liveness).', flows: [{ from: 'running', to: 'crash', label: 'exit 1', color: 'red' }, { from: 'crash', to: 'running', label: 'restart' }] },
    { caption: 'For Jobs (restartPolicy Never or OnFailure), when every container exits 0 the Pod reaches Succeeded, a terminal phase. Deployment Pods never get here because their containers are always restarted.', flows: [{ from: 'running', to: 'succeeded', label: 'all exit 0' }] },
    { caption: 'If containers terminate, at least one with a failure, and nothing will restart them, the Pod is Failed. Evictions for memory or disk pressure also leave Failed Pods (reason Evicted) behind for you to inspect.', flows: [{ from: 'running', to: 'failed', label: 'exit 1, Never', color: 'red' }] },
    { caption: 'If the node stops reporting, the state is unknown. After the 300 s unreachable toleration the Pod is evicted and its controller creates a replacement elsewhere. A StatefulSet waits until the old Pod is confirmed gone.', flows: [{ from: 'running', to: 'unknown', label: 'node lost' }] },
  ],
});

registerDiagram({
  id: 'k8s-graceful-shutdown',
  roadmap: 'kubernetes', module: 4, problem: 'Eliminate 502s during rollouts with graceful shutdown',
  kind: 'sequence',
  title: 'Pod termination: the endpoint-removal race',
  desc: 'When a Pod is deleted, removing it from load balancing and stopping its container happen in parallel, with nothing ordering them. Press Play to see why requests fail without a preStop delay.',
  actors: [
    { id: 'cl', label: 'Client', sub: 'via LB / Ingress', icon: '💻', color: 'gray', info: 'Sees a 502 or 503 when its request is routed to a Pod whose process has already exited.' },
    { id: 'px', label: 'Routing layer', sub: 'kube-proxy · Ingress', color: 'teal', info: 'Every kube-proxy, ingress controller, Gateway and mesh sidecar keeps its own copy of the endpoints, updated asynchronously from EndpointSlice watches.' },
    { id: 'ep', label: 'EndpointSlice ctrl', sub: 'controller-manager', color: 'purple', info: 'Maintains EndpointSlices for every Service, with per-endpoint conditions ready, serving and terminating.' },
    { id: 'api', label: 'kube-apiserver', sub: 'source of truth', color: 'blue', info: 'Sets deletionTimestamp and the grace period on delete; the object stays until the kubelet confirms the containers are gone.' },
    { id: 'kl', label: 'kubelet', sub: 'node of the old Pod', color: 'green', info: 'Runs the preStop hook, sends SIGTERM, waits for the grace period, then SIGKILL.' },
    { id: 'app', label: 'Go app', sub: 'old Pod (v1)', color: 'orange', info: 'Must handle SIGTERM: stop accepting, finish in-flight work and exit before the grace period ends.' },
  ],
  steps: [
    { section: 'A rollout deletes an old Pod' },
    { from: 'api', to: 'api', label: 'deletionTimestamp', caption: 'The Deployment scales the old ReplicaSet down and the API server marks a Pod for deletion (grace period 30 s by default). Two independent chains now start at the same time.' },
    { section: 'Chain A: remove it from load balancing' },
    { from: 'api', to: 'ep', label: 'Pod terminating', caption: 'The EndpointSlice controller sees the terminating Pod through its watch.' },
    { from: 'ep', to: 'api', label: 'ready=false', caption: 'It marks the endpoint ready=false, terminating=true in the EndpointSlice. New connections should stop going to this Pod, but only once everyone has seen the update.' },
    { from: 'api', to: 'px', label: 'EndpointSlice update', caption: 'Every kube-proxy, ingress controller and mesh proxy must receive the update and reprogram its rules. On a big cluster that takes from milliseconds to several seconds.' },
    { section: 'Chain B: stop the container' },
    { from: 'api', to: 'kl', label: 'Pod terminating', caption: 'At the same moment the kubelet sees the deletion. It runs the preStop hook first, and the grace-period clock starts now, not at SIGTERM.' },
    { from: 'kl', to: 'app', label: 'preStop: sleep 10s', caption: 'preStop simply waits a few seconds (the lifecycle sleep action needs no sleep binary, so it works on distroless). The app keeps serving normally while routes are removed everywhere.' },
    { section: 'The race window' },
    { from: 'cl', to: 'px', label: 'GET /orders', caption: 'Some routing layers have not processed the update yet and still pick this Pod for new connections.' },
    { from: 'px', to: 'app', label: 'routed to the old Pod (stale rules)', caption: 'Because the app is still serving during preStop, the request succeeds. Without the delay the process may already have exited: connection refused, which surfaces as 502 or 503 at the load balancer.' },
    { from: 'app', to: 'cl', label: '200 OK', reply: true, caption: 'Zero-downtime rollouts need endpoint removal to finish before the app stops listening. In practice only a preStop delay longer than the propagation time guarantees that ordering.' },
    { section: 'Drain and exit' },
    { from: 'kl', to: 'app', label: 'SIGTERM', caption: 'After preStop, the kubelet sends SIGTERM to PID 1. Use exec-form ENTRYPOINT (or tini) so the signal reaches the Go process; a shell wrapper swallows it and the Pod waits for SIGKILL.' },
    { from: 'app', to: 'app', label: 'Shutdown(ctx)', caption: 'http.Server.Shutdown stops accepting, waits for in-flight requests and closes idle keep-alive connections. Then close DB pools and flush telemetry.' },
    { from: 'app', to: 'kl', label: 'exit 0', reply: true, caption: 'The process exits within the grace period. If it is still running when terminationGracePeriodSeconds expires (counted from the start of preStop), the kubelet sends SIGKILL. Size it above preStop + the longest request.' },
    { from: 'kl', to: 'api', label: 'containers gone', caption: 'The kubelet reports the containers terminated and the Pod object is finally removed from the API.' },
  ],
});

registerDiagram({
  id: 'k8s-rolling-update',
  roadmap: 'kubernetes', module: 4, topic: 'ReplicaSets & Deployments: Rolling Updates and Rollbacks',
  kind: 'graph',
  title: 'Rolling update: ReplicaSet hand-over (maxSurge 1, maxUnavailable 0)',
  desc: 'A Deployment never updates Pods in place. It creates a new ReplicaSet and shifts replicas from old to new, gated by readiness. Press Play to watch 3 replicas move from v1 to v2.',
  groups: [
    { id: 'gOld', label: 'Pods of v1', x: 4, y: 0, w: 3, h: 1, color: 'blue' },
    { id: 'gNew', label: 'Pods of v2', x: 4, y: 2, w: 3, h: 1, color: 'green' },
  ],
  nodes: [
    { id: 'deploy', label: 'Deployment web', sub: 'replicas 3', x: 0, y: 1, color: 'purple', info: 'strategy.rollingUpdate: maxSurge 1 (at most 4 Pods exist) and maxUnavailable 0 (never fewer than 3 available). The defaults are 25% / 25%. Recreate kills all old Pods first instead.' },
    { id: 'rsOld', label: 'ReplicaSet v1', sub: 'hash 7d4f9c', x: 2, y: 0, color: 'blue', info: 'Named after the pod-template-hash. Old ReplicaSets are kept at 0 replicas (revisionHistoryLimit, default 10) as the rollback history.' },
    { id: 'rsNew', label: 'ReplicaSet v2', sub: 'hash 5b8d2e', x: 2, y: 2, color: 'green', enter: 2, info: 'Created because the Pod template changed (new image). Changing replicas alone never creates a new ReplicaSet.' },
    { id: 'o1', label: 'web-v1-a', sub: 'Ready', x: 4, y: 0, color: 'blue', exit: 7 },
    { id: 'o2', label: 'web-v1-b', sub: 'Ready', x: 5, y: 0, color: 'blue', exit: 6 },
    { id: 'o3', label: 'web-v1-c', sub: 'Ready', x: 6, y: 0, color: 'blue', exit: 4 },
    { id: 'n1', label: 'web-v2-a', sub: 'image :1.2', x: 4, y: 2, color: 'green', enter: 3 },
    { id: 'n2', label: 'web-v2-b', sub: 'image :1.2', x: 5, y: 2, color: 'green', enter: 5 },
    { id: 'n3', label: 'web-v2-c', sub: 'image :1.2', x: 6, y: 2, color: 'green', enter: 6 },
  ],
  edges: [
    { from: 'deploy', to: 'rsOld', label: 'scales' },
    { from: 'deploy', to: 'rsNew', label: 'scales' },
    { from: 'rsOld', to: 'o1', label: 'owns' },
    { from: 'rsNew', to: 'n1', label: 'owns' },
  ],
  steps: [
    { caption: 'Steady state: the Deployment owns ReplicaSet v1, which keeps 3 Ready Pods. The strategy allows 1 extra Pod (maxSurge) and 0 missing ones (maxUnavailable), so capacity never drops but the cluster needs room for a 4th Pod.', active: ['deploy', 'rsOld', 'o1', 'o2', 'o3'] },
    { caption: 'kubectl set image changes the Pod template. Only template changes trigger a rollout: the new pod-template-hash means a new ReplicaSet v2, created with 0 replicas.', flows: [{ from: 'deploy', to: 'rsNew', label: 'create, 0 replicas' }] },
    { caption: 'The controller scales v2 to 1: the surge Pod. 4 Pods exist, 3 of them available. Nothing old is deleted yet, because maxUnavailable is 0.', flows: [{ from: 'deploy', to: 'rsNew', label: 'scale to 1' }, { from: 'rsNew', to: 'n1', label: 'create' }] },
    { caption: 'web-v2-a passes readiness and stays Ready for minReadySeconds, so it counts as available. Only now is v1 scaled to 2. Readiness gates the whole rollout: a wrong probe means a stuck or broken rollout.', flows: [{ from: 'deploy', to: 'rsOld', label: 'scale to 2' }], active: ['n1'] },
    { caption: 'Again one surge Pod: v2 goes to 2. Each step waits for the previous new Pod to become available, so rollout speed is bounded by startup plus readiness time.', flows: [{ from: 'deploy', to: 'rsNew', label: 'scale to 2' }], active: ['n2'] },
    { caption: 'web-v2-b is Ready: v1 drops to 1 and v2 creates its third Pod. Old Pods leave through the normal termination sequence (endpoint removal, preStop, SIGTERM), so graceful shutdown still matters.', flows: [{ from: 'deploy', to: 'rsOld', label: 'scale to 1' }, { from: 'deploy', to: 'rsNew', label: 'scale to 3' }], active: ['n3'] },
    { caption: 'web-v2-c is Ready, v1 is scaled to 0 and the rollout is complete. ReplicaSet v1 is kept with 0 replicas so that kubectl rollout undo has something to go back to.', flows: [{ from: 'deploy', to: 'rsOld', label: 'scale to 0' }], active: ['n1', 'n2', 'n3'] },
    { caption: 'kubectl rollout undo copies v1\'s template back and the same surge logic runs in reverse. If new Pods never become Ready, the Deployment reports ProgressDeadlineExceeded after 600 s but does not roll back by itself.', active: ['deploy', 'rsOld', 'rsNew'] },
  ],
});

registerDiagram({
  id: 'k8s-statefulset',
  roadmap: 'kubernetes', module: 4, topic: 'StatefulSets',
  kind: 'graph',
  title: 'StatefulSet: ordered start, stable names, per-Pod storage',
  desc: 'Each replica has an ordinal, a DNS name and a PVC that survive rescheduling. Press Play to see ordered creation, a node failure and scale-down.',
  nodes: [
    { id: 'svc', label: 'Service db', sub: 'clusterIP: None', x: 0, y: 1, color: 'purple', info: 'The headless Service named in spec.serviceName. It has no virtual IP: DNS returns the Pod IPs, and each Pod gets its own record db-N.db.prod.svc.cluster.local.' },
    { id: 'db0', label: 'db-0', sub: 'db-0.db.prod.svc', x: 2, y: 0, color: 'green', enter: 1, info: 'Ordinal 0 is created first and is the natural bootstrap member (for example the initial primary).' },
    { id: 'db1', label: 'db-1', sub: 'db-1.db.prod.svc', x: 2, y: 1, color: 'green', enter: 2, exit: 5, info: 'Runs on node-b in this story.' },
    { id: 'db2', label: 'db-2', sub: 'db-2.db.prod.svc', x: 2, y: 2, color: 'green', enter: 3, exit: 7, info: 'The highest ordinal: removed first on scale-down and updated first on a rolling update.' },
    { id: 'pvc0', label: 'data-db-0', sub: 'PVC 10Gi RWO', x: 4, y: 0, shape: 'db', color: 'teal', enter: 1, info: 'Created from volumeClaimTemplates, named <template>-<pod>. It belongs to the ordinal, not to a node.' },
    { id: 'pvc1', label: 'data-db-1', sub: 'PVC 10Gi RWO', x: 4, y: 1, shape: 'db', color: 'teal', enter: 2, info: 'Survives the Pod. A zonal block disk (EBS, PD) can only attach to nodes in its zone.' },
    { id: 'pvc2', label: 'data-db-2', sub: 'PVC 10Gi RWO', x: 4, y: 2, shape: 'db', color: 'teal', enter: 3, info: 'Kept after scale-down by default (persistentVolumeClaimRetentionPolicy whenScaled: Retain).' },
    { id: 'db1b', label: 'db-1', sub: 'recreated on node-c', x: 6, y: 1, color: 'green', enter: 6, info: 'Same name, same DNS name, same PVC. Only the Pod IP and the node changed.' },
  ],
  edges: [
    { from: 'svc', to: 'db0' },
    { from: 'svc', to: 'db1' },
    { from: 'svc', to: 'db2' },
    { from: 'db0', to: 'pvc0', label: 'mounts /data' },
    { from: 'db1', to: 'pvc1' },
    { from: 'db2', to: 'pvc2' },
    { from: 'db1b', to: 'pvc1', label: 'same PVC' },
  ],
  steps: [
    { caption: 'With podManagementPolicy OrderedReady the controller creates db-0 first, plus its own PVC data-db-0 from volumeClaimTemplates. Nothing else happens until db-0 is Running and Ready.', flows: [{ from: 'db0', to: 'pvc0', label: 'bind PVC' }] },
    { caption: 'Only then is db-1 created, with data-db-1. It finds its peer at a stable DNS name, db-0.db.prod.svc.cluster.local, to join as a replica. That predictable bootstrap is why clustered databases use StatefulSets.', flows: [{ from: 'db1', to: 'pvc1', label: 'bind PVC' }, { from: 'db1', to: 'db0', label: 'join db-0.db' }] },
    { caption: 'db-2 follows the same way. podManagementPolicy Parallel skips the ordering when members do not need it, which makes scaling much faster.', flows: [{ from: 'db2', to: 'pvc2', label: 'bind PVC' }] },
    { caption: 'The headless Service gives no virtual IP and no load balancing: DNS returns every ready Pod IP, and each Pod has its own A record. Clients can address one specific member, such as the primary.', flows: [{ from: 'db0', to: 'svc', label: 'A 10.244.1.4' }, { from: 'db1', to: 'svc', label: 'A 10.244.2.7' }, { from: 'db2', to: 'svc', label: 'A 10.244.3.2' }] },
    { caption: 'node-b dies and db-1 is gone. The controller will not start a second db-1 while the old one might still run: at most one Pod per identity protects the volume. The node must return or be deleted, or the Pod force-deleted.', active: ['pvc1'] },
    { caption: 'db-1 is recreated with the same name, DNS name and PVC on another node. A zonal RWO disk attaches only in its own zone, so the Pod must fit on a node there or stay Pending.', flows: [{ from: 'db1b', to: 'pvc1', label: 'reattach' }] },
    { caption: 'Scale-down goes in reverse: db-2 is removed first and its PVC is kept, so scaling up again reuses the data. StatefulSets do not replicate data: Postgres or Kafka must, which is why operators are usually preferred.', active: ['pvc2'] },
  ],
});

