registerDiagram({
  id: 'k8s-service-path',
  roadmap: 'kubernetes', module: 5, topic: 'EndpointSlices & kube-proxy Modes',
  kind: 'graph',
  title: 'ClusterIP Service: control path and packet path',
  desc: 'A ClusterIP is not owned by any interface. The EndpointSlice controller and kube-proxy turn it into NAT rules on every node. Press Play to follow both the control path and one TCP connection.',
  groups: [
    { id: 'cp', label: 'Control plane', x: 0, y: 0, w: 3, h: 1, color: 'blue' },
    { id: 'n1', label: 'node-1', x: 0, y: 2, w: 3, h: 2, color: 'green' },
    { id: 'n2', label: 'node-2', x: 4, y: 2, w: 1, h: 2, color: 'green' },
  ],
  nodes: [
    { id: 'epc', label: 'Slice controller', sub: 'EndpointSlice ctrl', x: 0, y: 0, color: 'purple', info: 'Watches Services and Pods. For each Service it writes EndpointSlices (up to 100 endpoints each) with per-endpoint conditions ready, serving, terminating, plus zone and node hints. Endpoints (the old API) is deprecated.' },
    { id: 'api', label: 'kube-apiserver', sub: 'Services, slices', x: 2, y: 0, color: 'blue', info: 'Allocates the ClusterIP from the service CIDR when the Service is created.' },
    { id: 'kp', label: 'kube-proxy', sub: 'one per node', x: 2, y: 2, color: 'teal', info: 'A DaemonSet that watches Services and EndpointSlices and programs the node dataplane: iptables (classic), nftables (GA in 1.33, the recommended successor) or IPVS (deprecated in 1.35). Cilium can replace it entirely with eBPF.' },
    { id: 'rules', label: 'nftables rules', sub: 'ClusterIP → Pod IPs', x: 2, y: 3, color: 'orange', info: 'In iptables mode: KUBE-SERVICES → KUBE-SVC-xxx → KUBE-SEP-xxx chains, each endpoint picked with a random probability. nftables uses verdict maps, so updates and lookups stay fast with many Services.' },
    { id: 'client', label: 'client Pod', sub: '10.244.1.5', x: 0, y: 3, color: 'gray', info: 'Resolves web.prod.svc.cluster.local to the ClusterIP 10.96.0.10 and opens a TCP connection to it.' },
    { id: 'b2', label: 'web Pod', sub: '10.244.2.4:8080', x: 4, y: 2, color: 'green', info: 'Another endpoint of the same Service.' },
    { id: 'b1', label: 'web Pod', sub: '10.244.2.9:8080', x: 4, y: 3, color: 'green', info: 'The chosen backend. Cross-node delivery is the CNI\'s job: native routing or an overlay (VXLAN/Geneve).' },
  ],
  edges: [
    { from: 'epc', to: 'api', both: true, label: 'watch Pods, write slices' },
    { from: 'api', to: 'kp', label: 'watch' },
    { from: 'kp', to: 'rules', label: 'program' },
    { from: 'client', to: 'rules' },
    { from: 'rules', to: 'b1' },
    { from: 'rules', to: 'b2' },
  ],
  steps: [
    { caption: 'Service web (selector app=web) gets a virtual ClusterIP, 10.96.0.10. The EndpointSlice controller lists the Pods matching the selector and writes their IPs and ready state into EndpointSlices.', flows: [{ from: 'api', to: 'epc', label: 'Pods app=web' }, { from: 'epc', to: 'api', label: 'EndpointSlice' }] },
    { caption: 'kube-proxy on every node watches Services and EndpointSlices and programs rules: "traffic to 10.96.0.10:80 goes to one of these Pod IPs on port 8080 (targetPort)".', flows: [{ from: 'api', to: 'kp', label: 'Service + slices' }, { from: 'kp', to: 'rules', label: 'sync rules' }] },
    { caption: 'The client Pod connects to 10.96.0.10:80. No interface owns that IP, which is why ping to a ClusterIP fails: test with curl or nc instead. The packet hits the NAT rules on its own node.', flows: [{ from: 'client', to: 'rules', label: 'SYN → 10.96.0.10' }] },
    { caption: 'The rules pick one endpoint and DNAT the destination to 10.244.2.9:8080. The CNI routes it to node-2. The choice happens once per connection, in the kernel of the client\'s node; no proxy process is in the path.', flows: [{ from: 'rules', to: 'b1', label: 'DNAT 10.244.2.9' }] },
    { caption: 'conntrack remembers the translation, so the reply is un-NATed and the client sees an answer from 10.96.0.10. Every later packet of this connection follows the same entry.', flows: [{ from: 'b1', to: 'rules', label: 'reply' }, { from: 'rules', to: 'client', label: 'from 10.96.0.10' }] },
    { caption: 'Load balancing is per connection, not per request. A long-lived HTTP/2 or gRPC connection stays pinned to one Pod while the other gets nothing. Fix it with client-side balancing over a headless Service, or an L7 proxy or mesh.', flows: [{ from: 'client', to: 'rules', label: 'same connection' }, { from: 'rules', to: 'b1', label: 'same Pod' }], active: ['b2'] },
    { caption: 'web 10.244.2.9 fails readiness: the controller marks it ready=false, kube-proxy drops it, and new connections go to the remaining endpoint. An empty slice is the classic "Service has no endpoints" symptom: check the selector.', flows: [{ from: 'epc', to: 'api', label: 'ready=false' }, { from: 'rules', to: 'b2', label: 'new connections' }] },
  ],
});

registerDiagram({
  id: 'k8s-coredns-ndots',
  roadmap: 'kubernetes', module: 5, topic: 'CoreDNS & Service Discovery',
  kind: 'sequence',
  title: 'Cluster DNS lookups and the ndots:5 tax',
  desc: 'The search list in a Pod\'s resolv.conf makes short Service names work, but it also turns every external lookup into several failed queries first. Press Play to compare an in-cluster and an external name.',
  actors: [
    { id: 'app', label: 'Go app Pod', sub: 'ns prod, ndots:5', icon: '📦', color: 'blue', info: 'The kubelet writes /etc/resolv.conf: nameserver 10.96.0.10, search prod.svc.cluster.local svc.cluster.local cluster.local, options ndots:5.' },
    { id: 'nl', label: 'NodeLocal DNSCache', sub: 'optional, per node', color: 'teal', info: 'A DaemonSet cache listening on a link-local IP (169.254.20.10) on every node. It avoids conntrack races for UDP and talks to CoreDNS over TCP.' },
    { id: 'dns', label: 'CoreDNS', sub: 'kube-dns 10.96.0.10', color: 'purple', info: 'A Deployment behind the kube-dns Service. The kubernetes plugin answers cluster.local from a watch cache of Services and EndpointSlices; cache and forward plugins handle the rest (Corefile ConfigMap).' },
    { id: 'up', label: 'Upstream DNS', sub: 'VPC / node resolver', color: 'gray', info: 'Receives everything outside cluster.local, as configured by the forward plugin.' },
  ],
  steps: [
    { section: 'In-cluster short name: orders' },
    { from: 'app', to: 'app', label: 'read resolv.conf', caption: '"orders" has fewer than 5 dots, so the resolver tries each search domain before the name itself. The first search domain is the Pod\'s own namespace.' },
    { from: 'app', to: 'dns', label: 'A? orders.prod.svc.cluster.local', caption: 'The first candidate is orders in the Pod\'s namespace. Short names therefore resolve within the namespace; use orders.billing for another one.' },
    { from: 'dns', to: 'app', label: 'A 10.96.12.7 (ClusterIP)', reply: true, caption: 'The kubernetes plugin answers from its cache: the ClusterIP, or every ready Pod IP for a headless Service. One round trip, as intended.' },
    { section: 'External name: api.github.com' },
    { from: 'app', to: 'dns', label: 'A? api.github.com.prod.svc.cluster.local', caption: 'api.github.com has only 2 dots, so it is also tried with every search suffix first.' },
    { from: 'dns', to: 'app', label: 'NXDOMAIN', reply: true, caption: 'Wasted query #1.' },
    { from: 'app', to: 'dns', label: 'A? …svc.cluster.local, …cluster.local', caption: 'Two more NXDOMAINs. Each lookup is usually sent for both A and AAAA, so one external name costs 6 or more extra queries: latency, CoreDNS load, and UDP conntrack races that show up as 5 s timeouts.' },
    { from: 'app', to: 'dns', label: 'A? api.github.com', caption: 'Only now is the name itself tried.' },
    { from: 'dns', to: 'up', label: 'forward', caption: 'Not in cluster.local, so the forward plugin sends it to the upstream resolver.' },
    { from: 'up', to: 'dns', label: 'A 140.82.112.5', reply: true, caption: 'CoreDNS caches the answer for its TTL.' },
    { from: 'dns', to: 'app', label: 'A 140.82.112.5', reply: true, caption: 'The app finally connects, after several unnecessary round trips.' },
    { section: 'Fixes' },
    { from: 'app', to: 'nl', label: 'A? api.github.com.', caption: 'A trailing dot makes the name fully qualified, so no search list is used. Alternatives: lower ndots to 2 with dnsConfig, and run NodeLocal DNSCache so queries stay on the node.' },
    { from: 'nl', to: 'app', label: 'cached answer', reply: true, caption: 'Answered from the node-local cache in well under a millisecond. Also scale CoreDNS with the cluster (cluster-proportional autoscaler) and allow UDP and TCP port 53 in egress NetworkPolicies.' },
  ],
});

registerDiagram({
  id: 'k8s-gateway-api',
  roadmap: 'kubernetes', module: 5, topic: 'Ingress & the Gateway API',
  kind: 'graph',
  title: 'Gateway API: role-oriented objects and request routing',
  desc: 'Infra providers own the GatewayClass, platform teams own Gateways, app teams own Routes in their namespaces. Press Play to set it up, then follow requests through path matching and a weighted canary.',
  groups: [
    { id: 'plat', label: 'platform team', x: 2, y: 0, w: 1, h: 2, color: 'blue' },
    { id: 'appt', label: 'app team · namespace shop', x: 4, y: 0, w: 3, h: 3, color: 'green' },
  ],
  nodes: [
    { id: 'client', label: 'Client', sub: 'shop.example.com', icon: '🌐', x: 0, y: 1, color: 'gray', info: 'Reaches the Gateway through a cloud load balancer that the Gateway controller provisioned.' },
    { id: 'secret', label: 'Secret shop-tls', sub: 'TLS certificate', x: 2, y: 0, color: 'yellow', info: 'Referenced by the listener (certificateRefs). If it lives in another namespace, that namespace must allow it with a ReferenceGrant. cert-manager can issue and renew it.' },
    { id: 'gw', label: 'Gateway', sub: 'listener HTTPS :443', x: 2, y: 1, color: 'blue', info: 'Listeners (port, protocol, hostname, TLS) plus allowedRoutes, which says which namespaces may attach routes. The controller turns it into a running proxy (Envoy, NGINX, a cloud LB).' },
    { id: 'gwc', label: 'GatewayClass', sub: 'infra provider', x: 2, y: 3, color: 'purple', info: 'Cluster-scoped. controllerName says which implementation handles Gateways of this class: Envoy Gateway, Istio, Cilium, NGINX Gateway Fabric, GKE, AWS and others.' },
    { id: 'route', label: 'HTTPRoute', sub: 'matches + weights', x: 4, y: 1, color: 'green', info: 'Owned by the app team. Matches on hostname, path, headers, query params and method; filters for redirects, rewrites, header changes and mirroring; timeouts. Its status shows whether the Gateway accepted it.' },
    { id: 'v1', label: 'Service web-v1', sub: 'weight 90', x: 6, y: 0, color: 'green', info: 'Stable version. Most implementations send traffic straight to the Pod IPs from the EndpointSlices, bypassing the ClusterIP.' },
    { id: 'apisvc', label: 'Service api', sub: 'path /api', x: 6, y: 1, color: 'green', info: 'A separate backend for the /api prefix.' },
    { id: 'v2', label: 'Service web-v2', sub: 'weight 10', x: 6, y: 2, color: 'orange', info: 'Canary version. Shifting the weights (manually or with Argo Rollouts / Flagger) progresses the release without any controller-specific annotations.' },
  ],
  edges: [
    { from: 'client', to: 'gw', label: 'HTTPS' },
    { from: 'gw', to: 'secret', label: 'certificateRefs' },
    { from: 'gw', to: 'gwc', label: 'gatewayClassName' },
    { from: 'route', to: 'gw', label: 'parentRefs' },
    { from: 'route', to: 'apisvc', label: '/api' },
    { from: 'route', to: 'v1', label: '/ 90%' },
    { from: 'route', to: 'v2', label: '/ 10%' },
  ],
  steps: [
    { caption: 'The infrastructure provider installs a controller and its GatewayClass. This replaces the IngressClass plus the pile of controller-specific annotations that Ingress needed.', active: ['gwc'] },
    { caption: 'The platform team creates a Gateway: a listener on 443 with the TLS certificate, and allowedRoutes limiting which namespaces may attach. The controller provisions the proxy and a load balancer.', flows: [{ from: 'gw', to: 'gwc', label: 'class' }, { from: 'gw', to: 'secret', label: 'load cert' }] },
    { caption: 'In namespace shop, the app team creates an HTTPRoute whose parentRefs point at the Gateway. They own their routing without touching shared infrastructure; the route status says whether it was accepted.', flows: [{ from: 'route', to: 'gw', label: 'attach' }] },
    { caption: 'A request arrives. The Gateway terminates TLS for shop.example.com (chosen by SNI) and looks for routes attached to that listener and hostname.', flows: [{ from: 'client', to: 'gw', label: 'GET /api/cart' }] },
    { caption: 'Path prefix /api matches, and the most specific match wins, so the request goes to the api Service. Header, query and method matches work the same way, with no annotations.', flows: [{ from: 'gw', to: 'route', label: 'match /api' }, { from: 'route', to: 'apisvc', label: 'GET /api/cart' }] },
    { caption: 'Everything else under / is split by weight: 90% to v1 and 10% to the v2 canary. Progressive delivery tools only need to edit these weights.', flows: [{ from: 'route', to: 'v1', label: '90%' }, { from: 'route', to: 'v2', label: '10%', color: 'orange' }] },
    { caption: 'Cross-namespace references, such as a route in shop using a Service in another namespace, need a ReferenceGrant in the target namespace. That explicit consent is what makes Gateway API safe for multi-tenant clusters.', active: ['secret', 'route', 'gw'] },
  ],
});

// ===== Module 6: Configuration & Storage =====================================

registerDiagram({
  id: 'k8s-dynamic-provisioning',
  roadmap: 'kubernetes', module: 6, topic: 'PersistentVolumes, PVCs & StorageClasses',
  kind: 'sequence',
  title: 'Dynamic provisioning with WaitForFirstConsumer',
  desc: 'A PVC asks for storage, a StorageClass says how to make it, a CSI driver creates the disk and the kubelet mounts it. Press Play to see why the disk is created only after the Pod is scheduled.',
  actors: [
    { id: 'u', label: 'You / StatefulSet', sub: 'creates PVC + Pod', color: 'gray', info: 'The PVC references storageClassName gp3. A StatefulSet creates the PVCs for you from volumeClaimTemplates.' },
    { id: 'sch', label: 'kube-scheduler', sub: 'VolumeBinding plugin', color: 'orange', info: 'The VolumeBinding filter checks that a node can reach the volume (PV node affinity, class allowedTopologies) and, for WaitForFirstConsumer, triggers provisioning in PreBind.' },
    { id: 'api', label: 'kube-apiserver', sub: 'PVC, PV, Pod', color: 'blue', info: 'Stores the PVC (namespaced claim), the PV (cluster-scoped volume) and the VolumeAttachment.' },
    { id: 'csi', label: 'CSI controller', sub: 'provisioner + attacher', color: 'purple', info: 'The CSI driver\'s controller Pod with sidecars: external-provisioner (CreateVolume), external-attacher (ControllerPublishVolume), external-resizer and snapshotter.' },
    { id: 'cloud', label: 'Cloud API', sub: 'EBS · PD · Azure Disk', color: 'yellow', info: 'Creates, attaches and deletes the actual block devices. Block disks are zonal and ReadWriteOnce.' },
    { id: 'kl', label: 'kubelet', sub: '+ CSI node plugin', color: 'green', info: 'The CSI node plugin (a DaemonSet) formats and mounts the device on the node: NodeStageVolume, then NodePublishVolume.' },
  ],
  steps: [
    { section: 'Claim' },
    { from: 'u', to: 'api', label: 'PVC data: gp3, 20Gi, RWO', caption: 'The StorageClass gp3 names the provisioner (ebs.csi.aws.com), its parameters, reclaimPolicy and volumeBindingMode WaitForFirstConsumer. The PVC stays Pending, by design, until a Pod uses it.' },
    { from: 'u', to: 'api', label: 'Pod mounting PVC data', caption: 'With Immediate binding the disk would already exist, possibly in a zone where the Pod cannot be scheduled. Waiting lets the scheduler decide first.' },
    { section: 'Schedule first, then provision' },
    { from: 'api', to: 'sch', label: 'unscheduled Pod', reply: true, caption: 'The scheduler picks up the Pod. Its filters include CPU and memory requests, taints and affinity, plus volume topology.' },
    { from: 'sch', to: 'sch', label: 'filter + score', caption: 'It chooses node-1 in zone eu-west-1a.' },
    { from: 'sch', to: 'api', label: 'selected-node=node-1', caption: 'In PreBind it annotates the PVC with volume.kubernetes.io/selected-node and waits for the claim to be bound before binding the Pod.' },
    { from: 'api', to: 'csi', label: 'PVC + selected node', caption: 'external-provisioner watches PVCs of its StorageClass and sees the annotation, so it knows which zone to use.' },
    { from: 'csi', to: 'cloud', label: 'CreateVolume (1a)', caption: 'It calls the CSI CreateVolume, which creates a 20 GiB gp3 disk in eu-west-1a with the class parameters (IOPS, encryption key).' },
    { from: 'cloud', to: 'csi', label: 'vol-0abc', reply: true, caption: 'The disk exists, but nothing is attached yet.' },
    { from: 'csi', to: 'api', label: 'create PV, bind to PVC', caption: 'It creates a PV with node affinity for zone 1a and a claimRef to the PVC. The PVC becomes Bound, one-to-one with this PV.' },
    { from: 'sch', to: 'api', label: 'bind Pod → node-1', caption: 'Now the scheduler binds the Pod to node-1.' },
    { section: 'Attach and mount' },
    { from: 'api', to: 'csi', label: 'VolumeAttachment', caption: 'The attach/detach controller creates a VolumeAttachment, and external-attacher calls ControllerPublishVolume.' },
    { from: 'csi', to: 'cloud', label: 'attach to node-1', caption: 'The cloud attaches the disk to node-1. A second node attaching the same RWO disk produces the Multi-Attach error.' },
    { from: 'api', to: 'kl', label: 'Pod on node-1', caption: 'The kubelet on node-1 sees the Pod and waits for the volume to be attached.' },
    { from: 'kl', to: 'kl', label: 'NodeStage+Publish', caption: 'The CSI node plugin formats the device on first use, mounts it at a staging path, then bind-mounts it into the Pod. Only then does the container start.' },
    { section: 'Delete' },
    { from: 'u', to: 'api', label: 'delete PVC', caption: 'reclaimPolicy Delete (the default for dynamic classes) deletes the cloud disk and its data. Use Retain for anything precious. The pvc-protection finalizer delays deletion while a Pod still uses the claim.' },
  ],
});

// ===== Module 7: Scheduling, Resources & Scaling =============================

registerDiagram({
  id: 'k8s-scheduler-cycle',
  roadmap: 'kubernetes', module: 7, topic: 'Scheduler Internals, Priority & Preemption',
  kind: 'graph',
  title: 'One scheduling cycle: filter → score → bind (and preemption)',
  desc: 'The scheduler handles one Pod at a time. Hard constraints remove nodes, soft preferences rank the rest, and the winner is written as a Binding. Press Play to schedule a Pod requesting 2 CPU.',
  groups: [
    { id: 'nodes', label: 'cluster nodes', x: 3, y: 0, w: 1, h: 4, color: 'green' },
  ],
  nodes: [
    { id: 'pod', label: 'Pending Pod', sub: 'requests 2 CPU', x: 0, y: 0, shape: 'pill', color: 'yellow', info: 'spec.nodeName is empty. It waits in the scheduling queue, sorted by priority (PriorityClass), then by creation time.' },
    { id: 'filter', label: 'Filter', sub: 'hard constraints', x: 0, y: 1, color: 'orange', info: 'NodeResourcesFit (requests vs allocatable), NodeAffinity / nodeSelector, TaintToleration, PodTopologySpread with DoNotSchedule, InterPodAffinity, VolumeBinding and VolumeZone, NodePorts, NodeUnschedulable.' },
    { id: 'score', label: 'Score', sub: 'soft preferences', x: 0, y: 2, color: 'orange', info: 'Each plugin returns 0–100, multiplied by its weight: NodeResourcesFit (LeastAllocated spreads, MostAllocated bin-packs), BalancedAllocation, ImageLocality, preferred affinity, ScheduleAnyway spread.' },
    { id: 'bind', label: 'Reserve → Bind', sub: 'write the Binding', x: 0, y: 3, color: 'blue', info: 'Reserve claims the resources in the scheduler cache, Permit can hold the Pod (gang scheduling), PreBind does work such as volume provisioning, Bind sets spec.nodeName. Binding runs asynchronously so the next Pod can start.' },
    { id: 'na', label: 'node-a', sub: '1 CPU free', x: 3, y: 0, color: 'green', info: 'Free capacity is allocatable minus the sum of requests of Pods already on the node. Actual usage does not matter to the scheduler.' },
    { id: 'nb', label: 'node-b', sub: 'taint gpu=true', x: 3, y: 1, color: 'green', info: 'A NoSchedule taint repels every Pod that does not tolerate it. A toleration allows a node; it does not attract the Pod there (use affinity for that).' },
    { id: 'nc', label: 'node-c', sub: '4 CPU, image cached', x: 3, y: 2, color: 'green', info: 'Feasible, has the most free room (LeastAllocated) and already has the image (ImageLocality).' },
    { id: 'nd', label: 'node-d', sub: '3 CPU free', x: 3, y: 3, color: 'green', info: 'Feasible but scores lower.' },
  ],
  edges: [
    { from: 'pod', to: 'filter' },
    { from: 'filter', to: 'score', label: 'feasible: c, d' },
    { from: 'score', to: 'bind', label: 'best: node-c' },
  ],
  steps: [
    { caption: 'A Pod with no nodeName enters the active queue, ordered by priority. PreFilter precomputes what the filters need, for example the Pod\'s total requests and its affinity terms.', flows: [{ from: 'pod', to: 'filter', label: 'next in queue' }] },
    { caption: 'Filter plugins check every node in parallel. node-a fails NodeResourcesFit: requests, not real usage, must fit into allocatable. node-b fails TaintToleration because the Pod does not tolerate gpu=true.', flows: [{ from: 'filter', to: 'na', label: 'Insufficient cpu', color: 'red' }, { from: 'filter', to: 'nb', label: 'untolerated taint', color: 'red' }] },
    { caption: 'node-c and node-d are feasible. On large clusters the scheduler stops once it has found enough feasible nodes (percentageOfNodesToScore) instead of checking all of them.', flows: [{ from: 'filter', to: 'nc', label: 'feasible' }, { from: 'filter', to: 'nd', label: 'feasible' }] },
    { caption: 'Score plugins rank them: free resources (spread or bin-pack, depending on the profile), image already present, preferred affinity and topology spread. node-c wins.', flows: [{ from: 'score', to: 'nc', label: 'score 87' }, { from: 'score', to: 'nd', label: 'score 62' }] },
    { caption: 'Reserve, Permit and PreBind run, then Bind writes spec.nodeName = node-c through the Binding subresource. The kubelet on node-c takes it from there.', flows: [{ from: 'bind', to: 'nc', label: 'nodeName=node-c' }] },
    { caption: 'If no node passed the filters, the Pod stays Pending with a FailedScheduling event such as "0/4 nodes are available: 1 Insufficient cpu, 1 node(s) had untolerated taint". It is retried on cluster events; node autoscalers react to it.', active: ['pod', 'filter', 'na', 'nb'] },
    { caption: 'Preemption (PostFilter): if the Pod has higher priority, the scheduler looks for a node where evicting lower-priority Pods makes it fit, evicts them gracefully and sets nominatedNodeName. PDBs are respected only on a best-effort basis.', flows: [{ from: 'filter', to: 'na', label: 'evict low-prio', color: 'red' }] },
  ],
});

registerDiagram({
  id: 'k8s-hpa-loop',
  roadmap: 'kubernetes', module: 7, topic: 'Pod Autoscaling: HPA, VPA & KEDA',
  kind: 'graph',
  title: 'The HPA control loop: metrics to replicas',
  desc: 'The HorizontalPodAutoscaler is just another controller: read a metric, compute a replica count, write it to the scale subresource. Press Play to follow one scale-up from 4 to 6 Pods.',
  nodes: [
    { id: 'pods', label: 'web Pods ×4', sub: 'request cpu 500m', x: 0, y: 0, color: 'yellow', info: 'CPU utilization is measured as a percentage of the request. A container without a CPU request gives the HPA nothing to compute: the target shows <unknown>.' },
    { id: 'kubelet', label: 'kubelet', sub: 'cAdvisor, cgroups', x: 2, y: 0, color: 'green', info: 'Reads per-container CPU and memory usage from cgroups and exposes it at /metrics/resource.' },
    { id: 'ms', label: 'metrics-server', sub: 'latest sample only', x: 4, y: 0, color: 'teal', info: 'Scrapes every kubelet (every 15 s by default), keeps only the latest values in memory and serves them through the aggregated API metrics.k8s.io. It also powers kubectl top. It is not a monitoring system.' },
    { id: 'api', label: 'kube-apiserver', sub: 'metrics.k8s.io', x: 4, y: 2, color: 'blue', info: 'Proxies the resource, custom and external metrics APIs to the registered adapters (APIService objects).' },
    { id: 'hpa', label: 'HPA controller', sub: 'every 15 s', x: 2, y: 2, color: 'purple', info: 'Runs in kube-controller-manager. desired = ceil(current × currentMetric / target), skipped within a 10% tolerance, max across all metrics. Pods that are not ready yet or have no metrics are handled conservatively.' },
    { id: 'deploy', label: 'Deployment web', sub: 'scale subresource', x: 0, y: 2, color: 'purple', info: 'The HPA writes spec.replicas through /scale. If GitOps also manages replicas in Git they fight: remove replicas from the manifest or ignore that field.' },
    { id: 'keda', label: 'KEDA / adapter', sub: 'external metrics', x: 6, y: 2, color: 'orange', info: 'Prometheus Adapter serves custom.metrics.k8s.io; KEDA serves external.metrics.k8s.io from 60+ sources (Kafka lag, SQS depth, cron) and handles scaling between 0 and 1 itself.' },
  ],
  edges: [
    { from: 'pods', to: 'kubelet', label: 'cgroup usage' },
    { from: 'kubelet', to: 'ms', label: 'scrape /metrics/resource' },
    { from: 'ms', to: 'api', label: 'aggregated API' },
    { from: 'hpa', to: 'api', label: 'GET metrics' },
    { from: 'hpa', to: 'deploy', label: 'PATCH /scale' },
    { from: 'deploy', to: 'pods', label: 'ReplicaSet scales' },
    { from: 'keda', to: 'api', label: 'external.metrics.k8s.io' },
  ],
  steps: [
    { caption: 'Each web Pod requests 500m CPU and is using about 450m: 90% utilization. The target in the HPA is 60%. The kubelet reads the usage from the containers\' cgroups.', flows: [{ from: 'pods', to: 'kubelet', label: '450m of 500m' }] },
    { caption: 'metrics-server scrapes every kubelet and serves the latest values through the aggregated metrics.k8s.io API. If metrics-server is missing or broken, the HPA shows <unknown> and never scales.', flows: [{ from: 'kubelet', to: 'ms', label: 'scrape' }, { from: 'ms', to: 'api', label: 'PodMetrics' }] },
    { caption: 'Every 15 s the HPA controller fetches the metrics for the Pods selected by the Deployment and averages them: 90%.', flows: [{ from: 'api', to: 'hpa', label: 'avg 90%' }] },
    { caption: 'desired = ceil(4 × 90 / 60) = 6. A ratio within 10% of 1.0 would be ignored to avoid jitter. With several metrics, the HPA takes the highest result, so any one of them can drive scale-up.', active: ['hpa'] },
    { caption: 'The HPA writes replicas: 6 to the scale subresource and the ReplicaSet creates 2 Pods. If they do not fit on any node they stay Pending, and that is the signal Cluster Autoscaler or Karpenter acts on.', flows: [{ from: 'hpa', to: 'deploy', label: 'replicas: 6' }, { from: 'deploy', to: 'pods', label: '+2 Pods' }] },
    { caption: 'Scale-down is deliberately slow: the default stabilization window is 300 s, so the HPA uses the highest recommendation of the last 5 minutes. behavior policies limit how fast it may add or remove Pods.', active: ['hpa', 'deploy'] },
    { caption: 'CPU is a lagging signal for queue workers. KEDA or an adapter exposes queue lag or RPS as external metrics so the HPA scales on demand instead; KEDA can also scale to zero when the queue is empty.', flows: [{ from: 'keda', to: 'api', label: 'queue lag 12k' }, { from: 'api', to: 'hpa', label: 'external metric' }] },
  ],
});

// ===== Module 8: Kubernetes Security =========================================

registerDiagram({
  id: 'k8s-rbac-flow',
  roadmap: 'kubernetes', module: 8, topic: 'API Authentication & RBAC Authorization',
  kind: 'graph',
  title: 'Authentication, then RBAC: subject → binding → role',
  desc: 'Kubernetes has no User objects: authentication turns a credential into a username and groups, then RBAC looks for a binding that grants the verb on the resource. Press Play to follow kubectl get pods -n shop.',
  groups: [
    { id: 'apis', label: 'kube-apiserver', x: 2, y: 0, w: 5, h: 1, color: 'blue' },
    { id: 'objs', label: 'RBAC objects', x: 2, y: 2, w: 3, h: 1, color: 'purple' },
  ],
  nodes: [
    { id: 'req', label: 'alice', sub: 'kubectl get pods', icon: '🧑‍💻', x: 0, y: 0, color: 'gray', info: 'Her kubeconfig uses an OIDC exec plugin (kubelogin) that fetches a short-lived ID token from the company IdP.' },
    { id: 'authn', label: 'Authentication', sub: 'who is calling?', x: 2, y: 0, color: 'blue', info: 'Tries the configured authenticators: client certificates (CN = user, O = groups), OIDC tokens, ServiceAccount tokens, webhook. Failure is 401. The result is a username plus groups, nothing is stored.' },
    { id: 'authz', label: 'RBAC authorizer', sub: 'is it allowed?', x: 4, y: 0, color: 'blue', info: 'Usually runs as Node,RBAC. Input: user, groups, verb, API group, resource, subresource, namespace, name. RBAC only allows; there are no deny rules. No match means 403.' },
    { id: 'adm', label: 'Admission', sub: 'then etcd', x: 6, y: 0, color: 'blue', info: 'Only authorized requests reach mutating and validating admission and then storage.' },
    { id: 'grp', label: 'Group dev-team', sub: 'from the OIDC claim', x: 0, y: 2, color: 'gray', info: 'Subjects are User, Group or ServiceAccount. Bind to IdP groups rather than individual users, so access follows team membership.' },
    { id: 'rb', label: 'RoleBinding', sub: 'namespace shop', x: 2, y: 2, color: 'purple', info: 'Grants the referenced role to its subjects within its own namespace only. A ClusterRoleBinding grants cluster-wide. roleRef is immutable.' },
    { id: 'role', label: 'ClusterRole view', sub: 'reusable rule set', x: 4, y: 2, color: 'purple', info: 'Rules are apiGroups + resources (+ subresources like pods/log, pods/exec) + verbs. A ClusterRole bound through a RoleBinding is the idiomatic way to reuse one role in many namespaces.' },
    { id: 'res', label: 'pods, services…', sub: 'in ns shop only', x: 6, y: 2, color: 'green', info: 'view deliberately excludes Secrets. Dangerous grants to watch for: secrets get/list, pods/exec, create Pods or workloads, impersonate, bind, escalate, nodes/proxy.' },
  ],
  edges: [
    { from: 'req', to: 'authn', label: 'Bearer token' },
    { from: 'authn', to: 'authz', label: 'user + groups' },
    { from: 'authz', to: 'adm', label: 'allowed' },
    { from: 'authz', to: 'rb', label: 'find bindings' },
    { from: 'rb', to: 'grp', label: 'subjects' },
    { from: 'rb', to: 'role', label: 'roleRef' },
    { from: 'role', to: 'res', label: 'get · list · watch' },
  ],
  steps: [
    { caption: 'alice runs kubectl get pods -n shop. kubectl sends her OIDC ID token as a Bearer token over HTTPS.', flows: [{ from: 'req', to: 'authn', label: 'Bearer id-token' }] },
    { caption: 'The OIDC authenticator checks the signature against the issuer\'s keys, the audience and the expiry, then maps claims to username alice and groups [dev-team]. A bad token stops here with 401.', flows: [{ from: 'authn', to: 'authz', label: 'alice + [dev-team]' }] },
    { caption: 'The request becomes attributes: verb list, resource pods, API group "" (core), namespace shop. The authorizer looks for RoleBindings in shop and ClusterRoleBindings whose subjects match alice or one of her groups.', flows: [{ from: 'authz', to: 'rb', label: 'list pods in shop?' }] },
    { caption: 'RoleBinding dev-view in shop lists Group dev-team as a subject: a match.', flows: [{ from: 'rb', to: 'grp', label: 'subject match' }] },
    { caption: 'Its roleRef is the ClusterRole view. Because the binding is a RoleBinding, the ClusterRole\'s rules apply only inside shop. The same ClusterRole can be bound in 50 namespaces.', flows: [{ from: 'rb', to: 'role', label: 'roleRef' }] },
    { caption: 'A rule allows list on pods in the core group, so the request is allowed and moves on to admission. With no matching rule anywhere the answer is 403; there is nothing like a deny rule to override.', flows: [{ from: 'role', to: 'res', label: 'list pods ✓' }, { from: 'authz', to: 'adm', label: 'allowed' }] },
    { caption: 'RBAC blocks privilege escalation: you can only create a binding for permissions you already hold, unless you have bind or escalate. Check effective access with kubectl auth can-i --list --as alice -n shop.', active: ['rb', 'role', 'res'] },
  ],
});

registerDiagram({
  id: 'k8s-admission-chain',
  roadmap: 'kubernetes', module: 8, topic: 'Admission Control & Policy Engines',
  kind: 'graph',
  title: 'The API request pipeline: mutate, validate, persist',
  desc: 'Admission sits after authorization and before etcd. Mutations run first, so validators see the final object. Press Play to send a Pod through the chain, see it denied, and see what a broken webhook does.',
  groups: [
    { id: 'apis', label: 'kube-apiserver', x: 2, y: 0, w: 1, h: 5, color: 'blue' },
  ],
  nodes: [
    { id: 'client', label: 'kubectl', sub: 'or a controller', icon: '🧑‍💻', x: 0, y: 0, color: 'gray', info: 'Controllers creating Pods (ReplicaSet, Job) go through exactly the same pipeline, which is why a broken webhook can stop a Deployment from creating Pods.' },
    { id: 'authn', label: 'Authentication', sub: '401 if unknown', x: 2, y: 0, color: 'blue', info: 'Who is calling: certificate, OIDC token or ServiceAccount token.' },
    { id: 'authz', label: 'Authorization', sub: 'RBAC: 403 if denied', x: 2, y: 1, color: 'blue', info: 'May this user do this verb on this resource? Admission never runs for requests that fail here.' },
    { id: 'mut', label: 'Mutating phase', sub: 'defaults, injection', x: 2, y: 2, color: 'orange', info: 'Built-ins such as ServiceAccount, DefaultStorageClass and LimitRanger defaults, then MutatingAdmissionPolicy (CEL) and mutating webhooks. Webhook order is not guaranteed; reinvocationPolicy can rerun them after later changes.' },
    { id: 'schema', label: 'Schema validation', sub: 'final object checked', x: 2, y: 3, color: 'blue', info: 'The mutated object is validated against the OpenAPI schema of its type (including CRD schemas and CEL x-kubernetes-validations).' },
    { id: 'val', label: 'Validating phase', sub: 'policies + webhooks', x: 2, y: 4, color: 'orange', info: 'Built-ins (PodSecurity, ResourceQuota, NodeRestriction), ValidatingAdmissionPolicy (CEL, GA in 1.30, in-process, no webhook to run) and validating webhooks. They can only accept or reject, and run in parallel.' },
    { id: 'etcd', label: 'etcd', sub: 'persisted', x: 2, y: 5, shape: 'db', color: 'teal', info: 'Only now does the object exist and become visible to controllers through their watches.' },
    { id: 'mwh', label: 'Mutating webhook', sub: 'e.g. Istio injector', x: 4, y: 2, color: 'purple', info: 'An HTTPS service you operate. It receives an AdmissionReview and answers with a JSONPatch, for example adding a sidecar container or default labels.' },
    { id: 'vwh', label: 'Policy webhook', sub: 'Kyverno, Gatekeeper', x: 4, y: 4, color: 'purple', info: 'Kyverno (policies as YAML, also mutate, generate and verifyImages) or OPA Gatekeeper (Rego). Roll new policies out in audit mode first, then enforce.' },
  ],
  edges: [
    { from: 'client', to: 'authn', label: 'POST Pod' },
    { from: 'authn', to: 'authz' },
    { from: 'authz', to: 'mut' },
    { from: 'mut', to: 'schema' },
    { from: 'schema', to: 'val' },
    { from: 'val', to: 'etcd', label: 'persist' },
    { from: 'mut', to: 'mwh', both: true, label: 'AdmissionReview' },
    { from: 'val', to: 'vwh', both: true, label: 'AdmissionReview' },
  ],
  steps: [
    { caption: 'A Pod create request arrives. It is authenticated (401 otherwise) and authorized by RBAC (403 otherwise). Admission only ever sees requests that are already allowed.', flows: [{ from: 'client', to: 'authn', label: 'POST Pod' }, { from: 'authn', to: 'authz', label: 'alice' }] },
    { caption: 'Mutating admission runs first: built-in plugins fill defaults, such as the ServiceAccount token volume and LimitRanger default requests.', flows: [{ from: 'authz', to: 'mut', label: 'allowed' }] },
    { caption: 'Then mutating webhooks are called over HTTPS with an AdmissionReview. A mesh injector answers with a JSONPatch that adds a sidecar container.', flows: [{ from: 'mut', to: 'mwh', label: 'AdmissionReview' }, { from: 'mwh', to: 'mut', label: 'patch: +sidecar' }] },
    { caption: 'The mutated object is validated against its schema. Validation comes after mutation on purpose: policies must judge what will actually be stored, sidecar included.', flows: [{ from: 'mut', to: 'schema', label: 'final object' }] },
    { caption: 'Validating admission: PodSecurity checks the namespace\'s level, ResourceQuota checks the budget, ValidatingAdmissionPolicy evaluates CEL in-process, and validating webhooks are called.', flows: [{ from: 'schema', to: 'val', label: 'validate' }, { from: 'val', to: 'vwh', label: 'AdmissionReview' }] },
    { caption: 'The Kyverno policy disallow-latest-tag rejects image web:latest. Any single rejection fails the request with the policy\'s message, and nothing is stored. Only allowed objects are persisted.', flows: [{ from: 'vwh', to: 'val', label: 'denied: :latest', color: 'red' }] },
    { caption: 'With a pinned tag the request passes every validator and is written to etcd. Only now can controllers and the scheduler see the Pod.', flows: [{ from: 'val', to: 'etcd', label: 'persist' }] },
    { caption: 'The webhook is down and failurePolicy is Fail: every matching write fails, cluster-wide. Scope webhooks with namespace and object selectors, exclude kube-system, use short timeouts and run them HA, or prefer in-process CEL policies.', flows: [{ from: 'val', to: 'vwh', label: 'timeout', color: 'red' }], active: ['client'] },
  ],
});

// ===== Module 9: Packaging, Delivery & GitOps ================================

registerDiagram({
  id: 'k8s-gitops-loop',
  roadmap: 'kubernetes', module: 9, topic: 'GitOps with Argo CD & Flux',
  kind: 'graph',
  title: 'GitOps: CI pushes images, Argo CD pulls desired state',
  desc: 'CI never touches the cluster. It publishes an image and proposes a change to the config repo; an agent inside the cluster pulls Git and reconciles. Press Play to ship a change, then watch drift get reverted.',
  groups: [
    { id: 'cl', label: 'prod cluster', x: 1, y: 2, w: 2, h: 3, color: 'blue' },
  ],
  nodes: [
    { id: 'dev', label: 'Developer', sub: 'merges a feature', icon: '🧑‍💻', x: 0, y: 0, color: 'gray' },
    { id: 'repo', label: 'App repo', sub: 'source code', x: 2, y: 0, color: 'gray', info: 'Application source and Dockerfile. Kept separate from environment config so that a config change does not trigger a full build and CI does not need write access to production config.' },
    { id: 'ci', label: 'CI pipeline', sub: 'test·build·scan·sign', x: 4, y: 0, color: 'orange', info: 'Tests, builds with BuildKit, scans (Trivy, Grype), generates an SBOM, signs with cosign keyless (OIDC identity of the pipeline) and pushes. It holds no cluster credentials.' },
    { id: 'reg', label: 'Registry', sub: 'signed, by digest', x: 6, y: 2, shape: 'db', color: 'yellow', info: 'Images are referenced by immutable digest (app@sha256:…) so what was tested is exactly what runs. An admission policy can require the cosign signature.' },
    { id: 'cfg', label: 'Config repo', sub: 'envs/prod overlay', x: 4, y: 2, color: 'teal', info: 'Desired state for each environment (Kustomize overlays or Helm values), one directory per environment. Promotion is a PR; rollback is git revert.' },
    { id: 'argo', label: 'Argo CD', sub: 'pull + reconcile', x: 2, y: 2, color: 'purple', info: 'Application = source (repo, path) + destination (cluster, namespace). syncPolicy.automated with prune and selfHeal. AppProjects restrict repos, destinations and kinds per team. Flux does the same with Kustomization and HelmRelease controllers.' },
    { id: 'app', label: 'Deployment web', sub: 'live state', x: 2, y: 4, color: 'green', info: 'Argo CD compares the rendered manifests with this live object. Fields owned by other controllers, such as replicas managed by an HPA, go in ignoreDifferences.' },
    { id: 'human', label: 'On-call', sub: 'kubectl edit', icon: '🧑', x: 0, y: 4, color: 'red', info: 'A manual hotfix in the cluster. With selfHeal it is reverted; without it, the app shows OutOfSync until Git catches up.' },
  ],
  edges: [
    { from: 'dev', to: 'repo', label: 'git push' },
    { from: 'repo', to: 'ci', label: 'webhook' },
    { from: 'ci', to: 'reg', label: 'push + cosign sign' },
    { from: 'ci', to: 'cfg', label: 'PR: new digest' },
    { from: 'argo', to: 'cfg', label: 'pull every 3 min' },
    { from: 'argo', to: 'app', label: 'apply, prune' },
    { from: 'human', to: 'app', label: 'drift' },
    { from: 'reg', to: 'app', label: 'pull image' },
  ],
  steps: [
    { caption: 'A developer merges a change to the app repo. Nothing about the cluster changes yet.', flows: [{ from: 'dev', to: 'repo', label: 'git push' }] },
    { caption: 'CI tests, builds, scans and signs the image, then pushes it by digest. CI has no cluster credentials at all: compromising CI does not hand out cluster-admin.', flows: [{ from: 'repo', to: 'ci', label: 'trigger' }, { from: 'ci', to: 'reg', label: 'web@sha256:9f…' }] },
    { caption: 'CI (or Argo CD Image Updater / Flux image automation) opens a PR that bumps the digest in the prod overlay. Review and merge is the deployment approval, with a full audit trail.', flows: [{ from: 'ci', to: 'cfg', label: 'PR: bump digest' }] },
    { caption: 'Argo CD notices the new commit (polling every ~3 minutes, or instantly via a Git webhook), renders the manifests with Kustomize or Helm and diffs them against the live state: OutOfSync.', flows: [{ from: 'cfg', to: 'argo', label: 'new commit' }] },
    { caption: 'Sync applies the change. Sync waves and hooks order resources (for example migrations first); prune deletes what was removed from Git; health checks report Healthy once the rollout finishes.', flows: [{ from: 'argo', to: 'app', label: 'sync' }, { from: 'reg', to: 'app', label: 'pull by digest' }] },
    { caption: 'During an incident someone runs kubectl edit and changes the live Deployment. Live state no longer matches Git, so Argo CD marks the app OutOfSync.', flows: [{ from: 'human', to: 'app', label: 'kubectl edit', color: 'red' }] },
    { caption: 'With selfHeal, Argo CD reverts the drift to what Git says. The only lasting way to change production is a commit, and rollback is git revert, which also means Git access control is now your deploy access control.', flows: [{ from: 'argo', to: 'app', label: 'revert drift' }] },
  ],
});

// ===== Module 10: Observability & Troubleshooting ============================

registerDiagram({
  id: 'k8s-probes',
  roadmap: 'kubernetes', module: 10, topic: 'Liveness, Readiness & Startup Probes',
  kind: 'graph',
  title: 'Startup, readiness and liveness: what each failure does',
  desc: 'All three probes are run by the kubelet, but their failures have very different effects: wait, stop sending traffic, or restart. Press Play to see each one, and the anti-pattern that causes restart storms.',
  groups: [
    { id: 'node', label: 'worker node', x: 0, y: 0, w: 3, h: 1, color: 'green' },
  ],
  nodes: [
    { id: 'kubelet', label: 'kubelet', sub: 'runs every probe', x: 0, y: 0, color: 'green', info: 'Probe types: httpGet, tcpSocket, exec, grpc. Settings: initialDelaySeconds, periodSeconds, timeoutSeconds (default 1 s), failureThreshold, successThreshold.' },
    { id: 'app', label: 'Go app container', sub: '/livez  /readyz', x: 2, y: 0, color: 'yellow', info: '/livez should only prove the process can make progress (no deadlock). /readyz may check critical dependencies and should fail as soon as shutdown starts.' },
    { id: 'svc', label: 'Service traffic', sub: 'only to Ready Pods', x: 2, y: 2, color: 'teal', info: 'kube-proxy, Ingress and Gateway controllers route only to endpoints marked ready in the EndpointSlices.' },
    { id: 'api', label: 'kube-apiserver', sub: 'Pod Ready condition', x: 0, y: 2, color: 'blue', info: 'The kubelet writes the Ready condition into the Pod status; the EndpointSlice controller turns it into endpoint conditions.' },
    { id: 'db', label: 'Postgres', sub: 'a dependency', x: 4, y: 0, shape: 'db', color: 'gray', info: 'A shared dependency. If every Pod\'s liveness depends on it, one database blip restarts the whole fleet.' },
  ],
  edges: [
    { from: 'kubelet', to: 'app', label: 'probe' },
    { from: 'svc', to: 'app', label: 'requests' },
    { from: 'kubelet', to: 'api', label: 'status' },
    { from: 'api', to: 'svc', label: 'EndpointSlices' },
    { from: 'app', to: 'db', dashed: true, label: 'liveness checks DB?' },
  ],
  steps: [
    { caption: 'The startup probe runs first; liveness and readiness are disabled until it succeeds. failureThreshold × periodSeconds (e.g. 30 × 10 s) is the startup budget. Better than a huge initialDelaySeconds on liveness.', flows: [{ from: 'kubelet', to: 'app', label: 'startup /livez' }] },
    { caption: 'Startup passed, readiness passes: the kubelet sets the Ready condition and the Pod\'s endpoint becomes ready. A rollout only proceeds when new Pods reach this point.', flows: [{ from: 'kubelet', to: 'app', label: '/readyz 200' }, { from: 'kubelet', to: 'api', label: 'Ready=True' }] },
    { caption: 'Now kube-proxy and the ingress route requests to it.', flows: [{ from: 'api', to: 'svc', label: 'endpoint ready' }, { from: 'svc', to: 'app', label: 'requests' }] },
    { caption: 'Readiness fails (overloaded, warming a cache, draining at shutdown): the Pod is removed from endpoints but not restarted, and gets traffic back once it passes again. This is the safe way to say "not right now".', flows: [{ from: 'kubelet', to: 'app', label: '/readyz 503', color: 'orange' }, { from: 'kubelet', to: 'api', label: 'Ready=False' }] },
    { caption: 'Liveness fails failureThreshold times in a row (a deadlocked process): the kubelet kills the container and restarts it. Use it only for states the app cannot recover from by itself; a crashed process is restarted anyway.', flows: [{ from: 'kubelet', to: 'app', label: '/livez timeout ×3', color: 'red' }] },
    { caption: 'Anti-pattern: liveness that checks the database. A short DB outage fails liveness in every replica at once, all of them restart, and a partial outage becomes a total one. Tight timeouts under CPU throttling cause the same storm.', flows: [{ from: 'db', to: 'app', label: 'DB down', color: 'red' }, { from: 'kubelet', to: 'app', label: 'restart all', color: 'red' }] },
  ],
});

registerDiagram({
  id: 'k8s-troubleshoot-flow',
  roadmap: 'kubernetes', module: 10, topic: 'Systematic Troubleshooting & kubectl debug',
  kind: 'graph',
  title: 'Pod troubleshooting decision tree',
  desc: 'Start from the STATUS column, read the evidence that matches it, then fix the cause. Press Play to walk through the six statuses you will meet most often in interviews and on call.',
  nodes: [
    { id: 'start', label: 'kubectl get pod', sub: 'then describe', x: 0, y: 2.5, shape: 'pill', color: 'gray', info: 'kubectl get pod -o wide shows status, restarts and node. kubectl describe pod shows conditions, container states, last termination and the events.' },
    { id: 'q', label: 'STATUS?', sub: 'phase / reason', x: 1, y: 2.5, shape: 'diamond', color: 'yellow' },
    { id: 's0', label: 'Pending', sub: 'no node yet', x: 3, y: 0, color: 'orange' },
    { id: 's1', label: 'ContainerCreating', sub: 'stuck for minutes', x: 3, y: 1, color: 'orange' },
    { id: 's2', label: 'ImagePullBackOff', sub: 'or ErrImagePull', x: 3, y: 2, color: 'red' },
    { id: 's3', label: 'CrashLoopBackOff', sub: 'restarts growing', x: 3, y: 3, color: 'red' },
    { id: 's4', label: 'Not Ready', sub: 'Running, READY 0/1', x: 3, y: 4, color: 'orange' },
    { id: 's5', label: 'Ready, no traffic', sub: 'Service fails', x: 3, y: 5, color: 'orange' },
    { id: 'c0', label: 'Cannot be scheduled', sub: 'requests, taints, affinity, PVC', x: 5, y: 0, w: 1.5, color: 'blue', info: 'Requests too large for any node\'s allocatable, untolerated taints, affinity or DoNotSchedule spread, PVC unbound or in another zone, ResourceQuota exceeded. A node autoscaler should react if a new node would help.' },
    { id: 'c1', label: 'Sandbox or volume setup', sub: 'Multi-Attach, missing Secret, CNI', x: 5, y: 1, w: 1.5, color: 'blue', info: 'RWO disk still attached to the old node (Multi-Attach), a referenced Secret or ConfigMap does not exist, the CNI cannot assign an IP (IP exhaustion, plugin down).' },
    { id: 'c2', label: 'Image cannot be pulled', sub: 'tag, registry auth, rate limit', x: 5, y: 2, w: 1.5, color: 'blue', info: 'The event text tells you which: "not found" (wrong name or tag), "unauthorized" (imagePullSecrets, node IAM role), "toomanyrequests" (Docker Hub limits), "no match for platform" (arm64 vs amd64), or DNS/network to the registry.' },
    { id: 'c3', label: 'Read the exit code', sub: '1 app · 137 OOM/kill · 127 cmd', x: 5, y: 3, w: 1.5, color: 'blue', info: 'lastState.terminated: exit 1 is usually app or config error (missing env var), 137 is SIGKILL (reason OOMKilled, or a liveness kill), 143 is SIGTERM, 126/127 means the command is not executable or not found.' },
    { id: 'c4', label: 'Probe failing', sub: 'path/port, slow start, deps', x: 5, y: 4, w: 1.5, color: 'blue', info: 'Events show "Readiness probe failed" with the status code or timeout. Check the port and path, add a startupProbe for slow starters, check the dependencies readiness waits for.' },
    { id: 'c5', label: 'Service has no endpoints', sub: 'selector, targetPort, 127.0.0.1', x: 5, y: 5, w: 1.5, color: 'blue', info: 'Selector does not match the Pod labels (empty EndpointSlice), targetPort points at the wrong port, the app listens on 127.0.0.1, or a NetworkPolicy drops the traffic. curl the Pod IP directly to split the problem in half.' },
    { id: 'dbg', label: 'kubectl debug', sub: 'ephemeral container', x: 0, y: 5, color: 'purple', info: 'kubectl debug -it pod/x --image=busybox --target=app shares the app\'s process namespace (works on distroless). --copy-to makes a copy with a different command for crash loops. kubectl debug node/n gives a shell with the host filesystem at /host.' },
  ],
  edges: [
    { from: 'start', to: 'q' },
    { from: 'q', to: 's0' }, { from: 'q', to: 's1' }, { from: 'q', to: 's2' },
    { from: 'q', to: 's3' }, { from: 'q', to: 's4' }, { from: 'q', to: 's5' },
    { from: 's0', to: 'c0', label: 'FailedScheduling' },
    { from: 's1', to: 'c1', label: 'describe: Events' },
    { from: 's2', to: 'c2', label: 'Events: Failed' },
    { from: 's3', to: 'c3', label: 'logs --previous' },
    { from: 's4', to: 'c4', label: 'Events: Unhealthy' },
    { from: 's5', to: 'c5', label: 'get endpointslices' },
  ],
  steps: [
    { caption: 'Observe before you change anything: the STATUS column, the restart count, then describe for conditions and events. Events expire after about an hour, so capture them early.', flows: [{ from: 'start', to: 'q', label: 'STATUS' }] },
    { caption: 'Pending means the scheduler could not place the Pod. The FailedScheduling event lists why per node, e.g. "0/5 nodes are available: 3 Insufficient cpu, 2 node(s) had untolerated taint". Requests count, not real usage.', flows: [{ from: 'q', to: 's0', label: 'Pending' }, { from: 's0', to: 'c0', label: 'why?' }] },
    { caption: 'Stuck in ContainerCreating means the Pod has a node but the kubelet cannot finish the sandbox: volume attach or mount errors, a referenced Secret or ConfigMap missing, or the CNI unable to give it an IP.', flows: [{ from: 'q', to: 's1', label: 'Creating' }, { from: 's1', to: 'c1', label: 'why?' }] },
    { caption: 'ImagePullBackOff: the exact registry error in the events tells you whether it is the name, auth, rate limiting, platform or network. Try pulling the same reference from the node with crictl pull.', flows: [{ from: 'q', to: 's2', label: 'BackOff' }, { from: 's2', to: 'c2', label: 'why?' }] },
    { caption: 'CrashLoopBackOff: the container starts and exits. The current container may have no logs yet, so read logs --previous and the last termination reason and exit code. OOMKilled points to limits or a leak.', flows: [{ from: 'q', to: 's3', label: 'CrashLoop' }, { from: 's3', to: 'c3', label: 'why?' }] },
    { caption: 'Running but not Ready: the readiness probe is failing, so the Pod gets no traffic and a rollout stalls. Wrong port or path, slow start without a startupProbe, or a dependency the probe waits for.', flows: [{ from: 'q', to: 's4', label: 'Not Ready' }, { from: 's4', to: 'c4', label: 'why?' }] },
    { caption: 'Ready Pods but the Service fails: check the EndpointSlices. Empty means the selector matches nothing; otherwise suspect targetPort, an app bound to 127.0.0.1, or a NetworkPolicy. Test the Pod IP, then the ClusterIP, then DNS.', flows: [{ from: 'q', to: 's5', label: 'no traffic' }, { from: 's5', to: 'c5', label: 'why?' }] },
    { caption: 'When you need to look inside: kubectl debug adds an ephemeral container with tools to a running Pod (essential for distroless images), copies a crashing Pod with a different command, or opens a shell on the node.', active: ['dbg', 's3', 'c3'] },
  ],
});

