registerDiagram({
  id: 'k8s-multistage-build',
  roadmap: 'kubernetes', module: 2, topic: 'Dockerfile Best Practices: Multi-stage, Non-root, Distroless',
  kind: 'graph',
  title: 'Multi-stage build: compile in a fat stage, ship a tiny one',
  desc: 'Only what you COPY --from the build stage reaches the final image; the toolchain, sources and caches are left behind. Press Play to build a Go service into a distroless, non-root image.',
  groups: [
    { id: 'gb', label: 'stage "build" (discarded)', x: 0, y: 0, w: 2, h: 4, color: 'orange' },
    { id: 'gf', label: 'final stage (shipped)', x: 4, y: 0, w: 2, h: 4, color: 'green' },
  ],
  nodes: [
    { id: 'bbase', label: 'FROM golang:1.25', sub: 'full toolchain, ~800 MB', x: 0, y: 0, w: 2, color: 'gray', info: 'The SDK image has the compiler, git and a shell. It is only used to produce the binary. FROM --platform=$BUILDPLATFORM lets it cross-compile natively instead of emulating arm64 with QEMU.' },
    { id: 'deps', label: 'COPY go.mod + download', sub: 'cache mount /go/pkg/mod', x: 0, y: 1, w: 2, color: 'blue', info: 'Copying only go.mod and go.sum first keeps this layer cached until dependencies change. RUN --mount=type=cache keeps the module cache in the builder, never in a layer.' },
    { id: 'build', label: 'COPY . + go build', sub: 'CGO_ENABLED=0 -trimpath', x: 0, y: 2, w: 2, color: 'blue', info: 'A static binary needs no libc, so it runs on distroless/static or scratch. -trimpath removes local paths; -ldflags="-s -w" strips symbol tables. Private module tokens come from RUN --mount=type=secret, never ARG or ENV.' },
    { id: 'bin', label: '/out/api', sub: 'static binary ~15 MB', x: 0, y: 3, w: 2, color: 'green', info: 'The only artifact the final stage needs.' },
    { id: 'fbase', label: 'FROM distroless/static', sub: 'CA certs, tzdata, ~2 MB', x: 4, y: 0, w: 2, color: 'gray', info: 'gcr.io/distroless/static-debian12:nonroot has no shell and no package manager, so there is little to exploit and few CVEs to patch. Use distroless/base or cc if the binary needs glibc (CGO).' },
    { id: 'copy', label: 'COPY --from=build', sub: '/out/api → /api', x: 4, y: 1, w: 2, color: 'blue', info: 'Copies files out of another stage. Nothing else from the build stage (sources, module cache, compiler, secrets used during the build) ends up in the final image.' },
    { id: 'user', label: 'USER 65532:65532', sub: 'non-root, numeric', x: 4, y: 2, w: 2, color: 'purple', info: 'A numeric UID lets Kubernetes verify runAsNonRoot without reading /etc/passwd. Pair it with readOnlyRootFilesystem and dropped capabilities in the Pod securityContext.' },
    { id: 'entry', label: 'ENTRYPOINT ["/api"]', sub: 'exec form → PID 1', x: 4, y: 3, w: 2, color: 'purple', info: 'Exec form runs the binary directly as PID 1 so it receives SIGTERM. Shell form would need /bin/sh, which distroless does not have, and the shell would swallow the signal.' },
    { id: 'img', label: 'api:1.4.2 @sha256', sub: '~17 MB, signed', x: 4, y: 5, w: 2, shape: 'db', color: 'yellow', info: 'Pushed by digest, scanned and signed. Typical result for a Go service: 1 GB single-stage image → under 20 MB.' },
    { id: 'gone', label: 'Build stage', sub: 'never pushed', x: 0, y: 5, w: 2, ghost: true, color: 'gray', info: 'Only the target (last) stage is exported. BuildKit also skips stages the target does not depend on, and builds independent stages in parallel.' },
  ],
  edges: [
    { from: 'bbase', to: 'deps' },
    { from: 'deps', to: 'build' },
    { from: 'build', to: 'bin' },
    { from: 'bin', to: 'copy', label: 'only this file' },
    { from: 'fbase', to: 'copy' },
    { from: 'copy', to: 'user' },
    { from: 'user', to: 'entry' },
    { from: 'entry', to: 'img', label: 'export + push' },
    { from: 'bin', to: 'gone', dashed: true },
  ],
  steps: [
    { caption: 'Stage one starts FROM the full Go SDK image. It is big, has a shell and a compiler, and that is fine: it exists only to produce a binary and is never shipped.', active: ['gb', 'bbase'] },
    { caption: 'Dependencies first: COPY go.mod go.sum, then go mod download with a BuildKit cache mount. A source edit does not invalidate this layer, so CI does not re-download modules on every commit.', flows: [{ from: 'bbase', to: 'deps', label: 'cached layer' }] },
    { caption: 'Then the source and go build with CGO_ENABLED=0: a fully static binary that needs no libc. TARGETOS and TARGETARCH cross-compile amd64 and arm64 without QEMU emulation.', flows: [{ from: 'deps', to: 'build', label: 'COPY . .' }, { from: 'build', to: 'bin', label: 'go build' }] },
    { caption: 'Stage two starts from scratch again, FROM distroless/static: CA certificates, timezone data and a nonroot user, but no shell and no package manager.', active: ['gf', 'fbase'] },
    { caption: 'COPY --from=build pulls exactly one file across. Sources, the module cache, the compiler and anything used during the build stay behind in stage one.', flows: [{ from: 'bin', to: 'copy', label: '/out/api' }, { from: 'fbase', to: 'copy', label: 'base layers' }] },
    { caption: 'USER 65532 with a numeric UID lets Kubernetes enforce runAsNonRoot; exec-form ENTRYPOINT makes the app PID 1 so SIGTERM reaches it and shutdown is graceful.', flows: [{ from: 'copy', to: 'user', label: 'non-root' }, { from: 'user', to: 'entry', label: 'PID 1' }] },
    { caption: 'Only the final stage is exported: a ~17 MB image with a tiny attack surface, pushed by digest, scanned and signed. The build stage never leaves the builder.', flows: [{ from: 'entry', to: 'img', label: 'push' }, { from: 'bin', to: 'gone', label: 'discarded' }] },
    { caption: 'No shell means kubectl exec sh fails. That is a feature: debug with kubectl debug and an ephemeral container instead. If the binary needs glibc, use distroless/base rather than adding Alpine.', active: ['fbase', 'entry'] },
  ],
});

registerDiagram({
  id: 'k8s-ha-control-plane',
  roadmap: 'kubernetes', module: 3, topic: 'Highly Available Control Plane',
  kind: 'graph',
  title: 'HA control plane: active-active API, Raft quorum, leader election',
  desc: 'Three control plane nodes in three zones with stacked etcd. Each component is made redundant differently. Press Play to follow a write, the leader lease, and what happens when a whole zone fails.',
  groups: [
    { id: 'za', label: 'control plane 1 · zone a', x: 3, y: 0, w: 3, h: 2, color: 'blue' },
    { id: 'zb', label: 'control plane 2 · zone b', x: 3, y: 3, w: 4, h: 2, color: 'blue' },
    { id: 'zc', label: 'control plane 3 · zone c', x: 3, y: 6, w: 3, h: 2, color: 'blue' },
  ],
  nodes: [
    { id: 'kubectl', label: 'kubectl / CI', sub: 'admins, pipelines', x: 0, y: 1, color: 'gray', info: 'kubeconfigs point at the load balancer DNS name, never at one control plane node.' },
    { id: 'kubelets', label: 'kubelets', sub: 'every worker node', x: 0, y: 5, color: 'gray', info: 'kubelets, kube-proxy and node agents also talk to the API through the load balancer address configured at join time.' },
    { id: 'lb', label: 'Load balancer', sub: 'VIP :6443 /readyz', x: 1, y: 3, color: 'orange', info: 'L4 TCP load balancer: a cloud LB, or kube-vip / keepalived + HAProxy on-prem. It health-checks /readyz and only forwards to healthy API servers. Its name must be in the API server certificate SANs.' },
    { id: 'apiA', label: 'kube-apiserver', sub: 'active', x: 3, y: 0, color: 'blue', info: 'Stateless: any replica can serve any request because all state is in etcd. That is why API servers are active-active.' },
    { id: 'etcdA', label: 'etcd', sub: 'Raft leader (now)', x: 5, y: 0, shape: 'db', color: 'teal', info: 'Stacked topology: one etcd member per control plane node. All writes go through the current Raft leader and commit once a majority has persisted them.' },
    { id: 'ctlA', label: 'scheduler, KCM', sub: 'leader: holds Lease', x: 3, y: 1, color: 'purple', info: 'kube-scheduler and kube-controller-manager run on every control plane node, but only the holder of their Lease in kube-system acts. Defaults: lease 15 s, renew deadline 10 s, retry every 2 s.' },
    { id: 'apiB', label: 'kube-apiserver', sub: 'active', x: 3, y: 3, color: 'blue', info: 'Same binary and config as the others. The LB spreads clients across all healthy replicas.' },
    { id: 'etcdB', label: 'etcd', sub: 'follower', x: 6, y: 3, shape: 'db', color: 'teal', info: 'Followers forward writes to the leader and replicate its log. If the leader stops sending heartbeats, a follower starts an election.' },
    { id: 'ctlB', label: 'scheduler, KCM', sub: 'standby', x: 3, y: 4, color: 'purple', info: 'Standbys keep trying to acquire the Lease. They take over only after the current holder fails to renew it for a full lease duration.' },
    { id: 'apiC', label: 'kube-apiserver', sub: 'active', x: 3, y: 6, color: 'blue', info: 'Three API servers tolerate losing one or two of them for serving; etcd quorum is the stricter limit.' },
    { id: 'etcdC', label: 'etcd', sub: 'follower', x: 5, y: 6, shape: 'db', color: 'teal', info: 'With 3 members, quorum is 2: the cluster survives one member failure. 5 members survive 2 failures but every write waits for 3 acknowledgements.' },
    { id: 'ctlC', label: 'scheduler, KCM', sub: 'standby', x: 3, y: 7, color: 'purple', info: 'A second standby. More standbys do not add capacity, only faster failover choices.' },
  ],
  edges: [
    { from: 'kubectl', to: 'lb', label: 'HTTPS' },
    { from: 'kubelets', to: 'lb' },
    { from: 'lb', to: 'apiA' },
    { from: 'lb', to: 'apiB', label: 'any healthy' },
    { from: 'lb', to: 'apiC' },
    { from: 'apiA', to: 'etcdA' },
    { from: 'apiB', to: 'etcdB' },
    { from: 'apiC', to: 'etcdC' },
    { from: 'ctlA', to: 'apiA' },
    { from: 'ctlB', to: 'apiB' },
    { from: 'ctlC', to: 'apiC' },
    { from: 'etcdA', to: 'etcdB', both: true },
    { from: 'etcdB', to: 'etcdC', both: true },
    { from: 'etcdA', to: 'etcdC', both: true, label: 'Raft' },
  ],
  steps: [
    { caption: 'Three control plane nodes in three zones, each running an API server, etcd, the scheduler and the controller-manager. A load balancer in front is the single address every client uses.', active: ['za', 'zb', 'zc', 'lb'] },
    { caption: 'API servers are active-active: they are stateless, so the load balancer can send any request to any healthy replica. It health-checks /readyz and stops sending traffic to one that is not ready.', flows: [{ from: 'kubectl', to: 'lb', label: 'kubectl apply' }, { from: 'lb', to: 'apiB', label: 'to replica 2' }] },
    { caption: 'A write reaches etcd. Member 2 forwards it to the Raft leader, which replicates it; it is committed once a majority (2 of 3) has persisted it. Only then does the API server answer.', flows: [{ from: 'apiB', to: 'etcdB', label: 'PUT' }, { from: 'etcdB', to: 'etcdA', label: 'to leader' }, { from: 'etcdA', to: 'etcdC', label: 'replicate' }] },
    { caption: 'Scheduler and controller-manager are active-passive. Node 1 holds the Lease and renews it every few seconds; the standbys keep checking it. Two active schedulers would make conflicting decisions.', flows: [{ from: 'ctlA', to: 'apiA', label: 'renew Lease' }, { from: 'ctlB', to: 'apiB', label: 'try acquire' }, { from: 'ctlC', to: 'apiC', label: 'try acquire' }] },
    { caption: 'Zone a goes dark. The load balancer health check fails and it stops routing to node 1. The etcd followers miss the leader heartbeats and elect a new leader among themselves.', flows: [{ from: 'lb', to: 'apiA', label: '/readyz fails', color: 'red' }, { from: 'etcdB', to: 'etcdC', label: 'elect leader' }] },
    { caption: 'After the Lease expires (about 15 s), a standby acquires it and resumes scheduling and reconciling. Workloads never stopped: running Pods do not depend on the control plane.', flows: [{ from: 'ctlB', to: 'apiB', label: 'Lease acquired' }, { from: 'lb', to: 'apiC', label: 'traffic' }], active: ['za'] },
    { caption: '2 of 3 etcd members is still a majority, so writes continue. Lose a second zone and etcd has no quorum: the API stops accepting changes, while running Pods keep serving. Hence 3 or 5 members, never 2 or 4.', flows: [{ from: 'etcdB', to: 'etcdC', label: 'quorum 2 of 3' }], active: ['etcdB', 'etcdC'] },
  ],
});

registerDiagram({
  id: 'k8s-blue-green-canary',
  roadmap: 'kubernetes', module: 4, topic: 'Release Strategies: Blue-Green & Canary',
  kind: 'graph',
  title: 'Blue-green switches all traffic at once; canary shifts it gradually',
  desc: 'Top: blue-green runs two full environments and flips a Service selector. Bottom: a canary gets a small weighted share while metrics decide whether it may grow. Press Play to compare both.',
  groups: [
    { id: 'gbg', label: 'blue-green: flip the Service selector', x: 0, y: 0, w: 7, h: 3, color: 'blue' },
    { id: 'gcn', label: 'canary: weighted traffic + analysis', x: 0, y: 4, w: 7, h: 3, color: 'orange' },
  ],
  nodes: [
    { id: 'u1', label: 'Users', sub: 'production traffic', icon: '🌐', x: 0, y: 1, color: 'gray' },
    { id: 'svc', label: 'Service web', sub: 'selector: color', x: 2, y: 1, color: 'purple', info: 'The production Service. Its selector (color: blue or green) decides which Deployment receives traffic. A Gateway backendRef can play the same role.' },
    { id: 'blue', label: 'web-blue (v1)', sub: '4 Pods · live', x: 4, y: 0, color: 'blue', info: 'The current version at full capacity.' },
    { id: 'green', label: 'web-green (v2)', sub: '4 Pods · idle', x: 4, y: 2, color: 'green', info: 'The new version, also at full capacity: blue-green needs twice the resources during the switch.' },
    { id: 'prev', label: 'Service preview', sub: 'selects green', x: 6, y: 2, color: 'purple', info: 'A second Service (or route) that always points at the idle colour, so you can run smoke and integration tests against v2 before it gets real users.' },
    { id: 'pipe', label: 'Pipeline', sub: 'tests, then switch', x: 6, y: 1, color: 'gray', info: 'CI/CD or Argo Rollouts (blueGreen strategy: activeService, previewService, prePromotionAnalysis, scaleDownDelaySeconds).' },
    { id: 'u2', label: 'Users', sub: 'production traffic', icon: '🌐', x: 0, y: 5, color: 'gray' },
    { id: 'route', label: 'HTTPRoute', sub: 'weights 90 / 10', x: 2, y: 5, color: 'purple', info: 'Gateway API backendRefs with weights give exact percentages. Without L7 routing, the share equals the replica ratio (1 canary Pod next to 9 stable ones is about 10%).' },
    { id: 'stable', label: 'api v1 (stable)', sub: '9 Pods · 90%', x: 4, y: 4, color: 'blue', info: 'Keeps serving the majority of traffic and is the baseline the canary is compared against.' },
    { id: 'canary', label: 'api v2 (canary)', sub: '1 Pod · 10%', x: 4, y: 6, color: 'orange', info: 'Small blast radius: if v2 is broken, only about 10% of requests are affected, and only for the analysis window.' },
    { id: 'prom', label: 'Prometheus', sub: 'errors · p99 latency', x: 6, y: 6, shape: 'db', color: 'teal', info: 'Both versions expose the same metrics, labelled by version, so the analysis can compare canary against stable rather than against a fixed number.' },
    { id: 'ctl', label: 'Argo Rollouts', sub: 'or Flagger', x: 6, y: 4, color: 'purple', info: 'Runs the steps: setWeight, pause, analysis. A failed AnalysisRun aborts the rollout and sets the canary weight back to 0 automatically.' },
  ],
  edges: [
    { from: 'u1', to: 'svc' },
    { from: 'svc', to: 'blue' },
    { from: 'svc', to: 'green' },
    { from: 'prev', to: 'green' },
    { from: 'pipe', to: 'prev' },
    { from: 'pipe', to: 'svc', label: 'patch selector' },
    { from: 'u2', to: 'route' },
    { from: 'route', to: 'stable' },
    { from: 'route', to: 'canary' },
    { from: 'stable', to: 'prom' },
    { from: 'canary', to: 'prom' },
    { from: 'ctl', to: 'prom' },
    { from: 'ctl', to: 'route', curve: -30 },
  ],
  steps: [
    { caption: 'Blue-green: v1 (blue) serves all users through Service web, whose selector is color: blue.', flows: [{ from: 'u1', to: 'svc', label: 'requests' }, { from: 'svc', to: 'blue', label: '100%' }] },
    { caption: 'v2 (green) is deployed next to it at full size and tested through a preview Service. Users are not affected yet, but you pay for two full environments.', flows: [{ from: 'pipe', to: 'prev', label: 'smoke tests' }, { from: 'prev', to: 'green', label: 'test traffic' }] },
    { caption: 'The switch: patch the Service selector to color: green. All new connections go to v2 at once. Long-lived keep-alive connections to blue drain over time.', flows: [{ from: 'pipe', to: 'svc', label: 'color=green' }, { from: 'svc', to: 'green', label: '100%' }] },
    { caption: 'Rollback is the same one-line switch back, as long as blue is still running, so keep it for a while. Both versions must work with the same database schema: use expand/contract migrations.', active: ['svc', 'blue', 'green'] },
    { caption: 'Canary: an HTTPRoute splits traffic 90/10 between the stable and canary Services. Only a small share of users sees v2.', flows: [{ from: 'u2', to: 'route', label: 'requests' }, { from: 'route', to: 'stable', label: '90%' }, { from: 'route', to: 'canary', label: '10%', color: 'orange' }] },
    { caption: 'Both versions report error rate and latency. The analysis compares canary against stable over the same window, which cancels out normal traffic swings.', flows: [{ from: 'stable', to: 'prom', label: 'metrics v1' }, { from: 'canary', to: 'prom', label: 'metrics v2' }] },
    { caption: 'Healthy: the controller queries Prometheus, sees the success rate above 99%, and raises the weight step by step (10 → 50 → 100). Finally the canary becomes the new stable.', flows: [{ from: 'ctl', to: 'prom', label: 'success 99.8%' }, { from: 'ctl', to: 'route', label: 'setWeight 50' }] },
    { caption: 'Unhealthy: the canary shows 4% errors, the AnalysisRun fails, and the controller sets the weight back to 0 and scales the canary down. Stable never stopped serving: rollback in seconds, no human needed.', flows: [{ from: 'canary', to: 'prom', label: '5xx 4%', color: 'red' }, { from: 'ctl', to: 'route', label: 'weight 0', color: 'red' }] },
  ],
});

registerDiagram({
  id: 'k8s-netpol-default-deny',
  roadmap: 'kubernetes', module: 5, topic: 'NetworkPolicy',
  kind: 'graph',
  title: 'NetworkPolicy: default-deny, then allow each flow explicitly',
  desc: 'Without policies every Pod can reach every Pod. Press Play to lock the shop namespace down with default-deny and then add back DNS, the gateway, frontend → backend and backend → database one by one.',
  groups: [
    { id: 'gsys', label: 'kube-system', x: 3, y: 0, w: 1, h: 1, color: 'gray' },
    { id: 'ggw', label: 'namespace gateway', x: 0, y: 1, w: 1, h: 1, color: 'purple' },
    { id: 'gshop', label: 'namespace shop: default-deny', x: 2, y: 1, w: 3, h: 3, color: 'green' },
  ],
  nodes: [
    { id: 'dns', label: 'CoreDNS', sub: 'k8s-app=kube-dns', x: 3, y: 0, color: 'blue', info: 'Every Pod needs it. Default-deny egress blocks DNS too, so allow UDP and TCP 53 to these Pods (namespaceSelector kube-system AND podSelector k8s-app=kube-dns in one entry).' },
    { id: 'gw', label: 'Gateway proxy', sub: 'Envoy, NGINX…', x: 0, y: 1, color: 'purple', info: 'North-south traffic enters here. The frontend allows ingress from this namespace by its kubernetes.io/metadata.name label.' },
    { id: 'fe', label: 'frontend', sub: 'app=frontend :8080', x: 2, y: 1, color: 'green', info: 'Needs ingress from the gateway, egress to backend and DNS. Each direction needs its own allow rule once default-deny selects the Pod.' },
    { id: 'be', label: 'backend', sub: 'app=backend :8080', x: 4, y: 1, color: 'green', info: 'Allows ingress only from app=frontend on its container port. Policies match Pod IPs and container ports after Service DNAT, so the Service port is irrelevant.' },
    { id: 'rogue', label: 'debug pod', sub: 'app=rogue', x: 2, y: 3, color: 'red', info: 'Any Pod someone starts in the namespace. With no policy allowing it, all its traffic is dropped, which also limits an attacker who compromises one workload.' },
    { id: 'db', label: 'postgres', sub: 'app=db :5432', x: 4, y: 3, shape: 'db', color: 'teal', info: 'Ingress only from app=backend on 5432. Everything else, including other Pods in the same namespace, is denied.' },
    { id: 'ext', label: 'payments API', sub: 'external HTTPS', icon: '🌐', x: 6, y: 1, ghost: true, color: 'gray', info: 'Egress outside the cluster: standard NetworkPolicy can only allow ipBlock CIDRs. FQDN rules (api.payments.com) need CNI-specific policies such as CiliumNetworkPolicy, or an egress gateway with fixed IPs.' },
    { id: 'cni', label: 'CNI agent', sub: 'enforces policies', x: 0, y: 3, color: 'orange', info: 'Policies are only API objects; the CNI (Calico, Cilium, cloud CNIs with policy enabled) programs them into each node. A CNI without policy support, such as plain Flannel, silently ignores them.' },
  ],
  edges: [
    { from: 'gw', to: 'fe' },
    { from: 'fe', to: 'be', label: 'TCP 8080' },
    { from: 'be', to: 'db', label: 'TCP 5432' },
    { from: 'fe', to: 'dns' },
    { from: 'be', to: 'dns' },
    { from: 'rogue', to: 'db' },
    { from: 'rogue', to: 'be' },
    { from: 'be', to: 'ext', label: 'HTTPS 443' },
  ],
  steps: [
    { caption: 'No policy selects these Pods, so the network is flat: the debug Pod can reach the database and the backend directly. Namespaces alone are not a network boundary.', flows: [{ from: 'rogue', to: 'db', label: 'allowed!', color: 'orange' }, { from: 'rogue', to: 'be', label: 'allowed!', color: 'orange' }] },
    { caption: 'Apply default-deny-all: podSelector {} with policyTypes Ingress and Egress. Every Pod in shop is now isolated in both directions, and even DNS lookups fail. This is the classic "everything broke" moment.', flows: [{ from: 'fe', to: 'dns', label: 'DNS blocked', color: 'red' }, { from: 'gw', to: 'fe', label: 'blocked', color: 'red' }] },
    { caption: 'allow-dns-egress: all Pods may send UDP and TCP 53 to CoreDNS. Policies are additive allow-lists: the union of all policies selecting a Pod is what it may do; there are no deny rules.', flows: [{ from: 'fe', to: 'dns', label: 'UDP/TCP 53' }, { from: 'be', to: 'dns', label: 'UDP/TCP 53' }] },
    { caption: 'Ingress to frontend from the gateway namespace on 8080. namespaceSelector and podSelector in the same entry mean AND; as two list entries they mean OR. One missing dash changes the meaning.', flows: [{ from: 'gw', to: 'fe', label: 'allowed' }] },
    { caption: 'frontend → backend needs two rules: egress on frontend and ingress on backend, both on container port 8080. Allowing only one side still drops the connection.', flows: [{ from: 'fe', to: 'be', label: 'TCP 8080' }] },
    { caption: 'backend → postgres on 5432 is allowed; the debug Pod matches no allow rule, so its connection is dropped. Test denials as carefully as allows.', flows: [{ from: 'be', to: 'db', label: 'allowed' }, { from: 'rogue', to: 'db', label: 'dropped', color: 'red' }] },
    { caption: 'Egress to the internet: an ipBlock for the provider CIDRs, or an FQDN policy from your CNI. Also block 169.254.169.254 so Pods cannot borrow the node cloud credentials.', flows: [{ from: 'be', to: 'ext', label: 'HTTPS 443' }] },
    { caption: 'Enforcement is the CNI job: on a CNI without policy support all of this silently does nothing. Verify with test Pods and watch drops in Hubble or Calico flow logs.', active: ['cni', 'rogue', 'db'] },
  ],
});

registerDiagram({
  id: 'k8s-node-autoscaling',
  roadmap: 'kubernetes', module: 7, topic: 'Node Autoscaling, PodDisruptionBudgets & Scaling Trade-offs',
  kind: 'graph',
  title: 'Node autoscaling: Pending Pods in, new nodes out (and back)',
  desc: 'Pod autoscalers create Pods; node autoscalers react to Pods that cannot be scheduled. Press Play to follow a scale-up end to end, then a consolidation that has to respect a PodDisruptionBudget.',
  groups: [
    { id: 'gw', label: 'worker nodes', x: 3, y: 4, w: 4, h: 1, color: 'green' },
  ],
  nodes: [
    { id: 'hpa', label: 'HPA', sub: 'replicas 6 → 10', x: 0, y: 0, color: 'purple', info: 'Scales Pods on CPU, RPS or queue metrics. It does not know or care whether there is room for the new Pods.' },
    { id: 'karp', label: 'Karpenter / CA', sub: 'watches Pending', x: 3, y: 0, color: 'purple', info: 'Cluster Autoscaler scales predefined node groups (ASG, MIG, VMSS) whose template would fit the Pods. Karpenter is group-less: it computes a right-sized instance from NodePool requirements (spot or on-demand, arch, families).' },
    { id: 'cloud', label: 'Cloud API', sub: 'EC2 · GCE · Azure', x: 6, y: 0, color: 'gray', info: 'Creates the VM. Spot capacity can be unavailable, so allow many instance types and zones.' },
    { id: 'pend', label: 'Pending Pods ×4', sub: 'FailedScheduling', x: 0, y: 2, shape: 'pill', color: 'yellow', info: 'Unschedulable because no node has enough allocatable CPU or memory for their requests. Requests decide this, not real usage: missing requests confuse every autoscaler.' },
    { id: 'sched', label: 'kube-scheduler', sub: 'binds Pods to nodes', x: 3, y: 2, color: 'blue', info: 'Marks the Pods unschedulable, which is the signal node autoscalers watch. Once a new node is Ready it binds them like any other Pod.' },
    { id: 'n1', label: 'node-1', sub: 'full (requests)', x: 3, y: 4, color: 'green', info: 'Allocatable is used up by the requests of the Pods already there, even if their actual CPU usage is low.' },
    { id: 'n2', label: 'node-2', sub: '20% allocated', x: 5, y: 4, color: 'green', info: 'After load drops this node is under-used: a consolidation candidate.' },
    { id: 'n3', label: 'new node', sub: 'right-sized, spot', x: 6, y: 4, color: 'green', enter: 5, info: 'Registered by its kubelet, Ready once the CNI is up. Typical time from decision to Ready: 1–3 minutes, then image pulls and app start.' },
    { id: 'pdb', label: 'PDB api', sub: 'maxUnavailable: 1', x: 5, y: 2, color: 'red', info: 'Limits voluntary disruptions through the Eviction API: drains, upgrades, consolidation. A PDB with 0 allowed disruptions blocks scale-down forever.' },
  ],
  edges: [
    { from: 'hpa', to: 'pend', label: 'creates Pods' },
    { from: 'pend', to: 'sched', label: 'unschedulable' },
    { from: 'karp', to: 'pend', label: 'watch' },
    { from: 'karp', to: 'cloud', label: 'launch instance' },
    { from: 'cloud', to: 'n3', label: 'VM joins' },
    { from: 'sched', to: 'n1' },
    { from: 'sched', to: 'n3' },
    { from: 'karp', to: 'n2', label: 'drain, delete' },
    { from: 'karp', to: 'pdb', label: 'eviction check' },
  ],
  steps: [
    { caption: 'Load rises and the HPA raises replicas from 6 to 10. The ReplicaSet creates 4 Pods immediately; whether they fit anywhere is not the HPA problem.', flows: [{ from: 'hpa', to: 'pend', label: '+4 Pods' }] },
    { caption: 'The scheduler finds no node with enough allocatable capacity for the Pods requests, so they stay Pending with a FailedScheduling event: "0/3 nodes are available: Insufficient cpu".', flows: [{ from: 'pend', to: 'sched', label: 'schedule me' }, { from: 'sched', to: 'n1', label: 'Insufficient cpu', color: 'red' }] },
    { caption: 'The node autoscaler watches unschedulable Pods and simulates scheduling. Cluster Autoscaler picks a node group whose template fits; Karpenter computes the cheapest instance type that fits all four.', flows: [{ from: 'pend', to: 'karp', label: '4 unschedulable' }] },
    { caption: 'It asks the cloud for capacity: Cluster Autoscaler raises the node group desired size, Karpenter creates the instance directly (a NodeClaim). Spot interruptions and stock-outs are why diverse instance types matter.', flows: [{ from: 'karp', to: 'cloud', label: 'create 1 VM' }] },
    { caption: 'The VM boots, the kubelet registers the Node and the CNI makes it Ready, typically 1–3 minutes after the decision. This is usually the slowest part of scaling.', flows: [{ from: 'cloud', to: 'n3', label: 'node Ready' }] },
    { caption: 'The scheduler binds the Pending Pods to the new node; then image pulls and app start. Total latency = metrics + HPA sync + node + pull + start; overprovisioning pause Pods hide the node part.', flows: [{ from: 'sched', to: 'n3', label: 'bind 4 Pods' }] },
    { caption: 'Later, load drops. Consolidation finds node-2 under-used, checks every PDB through the Eviction API, cordons the node, evicts its Pods one budget at a time and deletes the instance.', flows: [{ from: 'karp', to: 'pdb', label: '1 allowed' }, { from: 'karp', to: 'n2', label: 'drain + delete' }] },
    { caption: 'If a PDB allows 0 disruptions (minAvailable equal to replicas, or one replica with minAvailable 1), eviction returns 429 forever and the node never drains. Use maxUnavailable: 1 and at least 2 replicas.', flows: [{ from: 'karp', to: 'pdb', label: '0 allowed', color: 'red' }], active: ['n2'] },
  ],
});

registerDiagram({
  id: 'k8s-operator-reconcile',
  roadmap: 'kubernetes', module: 9, topic: 'Operators & Custom Resource Definitions',
  kind: 'graph',
  title: 'An operator reconciling a custom resource: children, finalizer, status',
  desc: 'A CRD adds the Database type; the operator turns each Database into a StatefulSet, Service and an external backup bucket, and reports progress in status. Press Play to create, repair and delete one.',
  nodes: [
    { id: 'user', label: 'kubectl apply', sub: 'db.yaml', x: 0, y: 0, color: 'gray', info: 'The platform user only writes the high-level intent: engine postgres, storage 50Gi, backups daily.' },
    { id: 'api', label: 'kube-apiserver', sub: 'CRD schema + CEL', x: 2, y: 0, color: 'blue', info: 'Validates the Database against the CRD OpenAPI schema and x-kubernetes-validations (CEL) before storing it. The status subresource lets the operator update status without touching spec.' },
    { id: 'op', label: 'db-operator', sub: 'Reconcile(ns/name)', x: 4, y: 0, color: 'purple', info: 'A controller built with controller-runtime: informers, a work queue, leader election. Reconcile is idempotent and level-triggered: it compares the whole desired state with the actual state on every call.' },
    { id: 'ext', label: 'Backup bucket', sub: 'outside the cluster', x: 6, y: 0, ghost: true, color: 'gray', info: 'External resources cannot carry ownerReferences, so the garbage collector cannot clean them up. That is the job of a finalizer.' },
    { id: 'cr', label: 'Database orders', sub: 'spec + status', x: 2, y: 2, shape: 'db', color: 'yellow', info: 'The custom resource. spec is desired state written by users; status (conditions, observedGeneration, endpoint) is written only by the operator.' },
    { id: 'sts', label: 'StatefulSet', sub: 'ownerRef: orders', x: 4, y: 2, color: 'green', info: 'A child object created by the operator with an ownerReference (controller: true) pointing at the Database. Owned children trigger reconciles of their owner when they change.' },
    { id: 'svc', label: 'Service, Secret', sub: 'ownerRef: orders', x: 6, y: 2, color: 'green', info: 'More children: a Service for clients and a Secret with generated credentials. Applied with server-side apply so the operator owns only the fields it sets.' },
    { id: 'gc', label: 'garbage collector', sub: 'follows ownerRefs', x: 4, y: 4, color: 'blue', info: 'Part of kube-controller-manager. When an owner is deleted it deletes the dependents (background cascading deletion by default).' },
  ],
  edges: [
    { from: 'user', to: 'api', label: 'apply' },
    { from: 'api', to: 'cr', label: 'persist' },
    { from: 'op', to: 'api', both: true, label: 'watch, update' },
    { from: 'op', to: 'sts', label: 'apply' },
    { from: 'op', to: 'svc', label: 'apply' },
    { from: 'op', to: 'ext', label: 'cloud API' },
    { from: 'sts', to: 'cr', dashed: true, label: 'ownerReference' },
    { from: 'gc', to: 'sts', label: 'cascade' },
  ],
  steps: [
    { caption: 'The CRD registered the Database type with a schema. A user applies a Database; the API server validates it (schema and CEL rules) and stores it. Without a controller, nothing else would happen.', flows: [{ from: 'user', to: 'api', label: 'Database orders' }, { from: 'api', to: 'cr', label: 'persist' }] },
    { caption: 'The operator watches Databases and the kinds it owns. The event enqueues the key shop/orders and Reconcile reads the desired spec from its informer cache.', flows: [{ from: 'api', to: 'op', label: 'watch event' }] },
    { caption: 'First it adds a finalizer to the Database, before creating anything external. From now on the object cannot disappear until the operator has cleaned up.', flows: [{ from: 'op', to: 'api', label: 'add finalizer' }], active: ['cr'] },
    { caption: 'It ensures the children exist and match, each with an ownerReference to the Database: a StatefulSet, a Service and a credentials Secret. Running this twice changes nothing: idempotent.', flows: [{ from: 'op', to: 'sts', label: 'apply' }, { from: 'op', to: 'svc', label: 'apply' }] },
    { caption: 'External resources such as the backup bucket are created through the cloud API. They cannot be owned by a Kubernetes object, which is exactly why the finalizer exists.', flows: [{ from: 'op', to: 'ext', label: 'create bucket' }] },
    { caption: 'It records progress in status: conditions (Ready=True, reason Provisioned) and observedGeneration. Only write status when it changed, or every write triggers another reconcile: a hot loop.', flows: [{ from: 'op', to: 'api', label: 'status: Ready' }] },
    { caption: 'Drift: someone deletes the Service. Because the operator watches owned children, the owner is reconciled again and the Service is recreated. Level-triggered: it acts on state, not on events.', flows: [{ from: 'svc', to: 'op', label: 'deleted', color: 'red' }, { from: 'op', to: 'svc', label: 'recreate' }] },
    { caption: 'Delete the Database: it only gets a deletionTimestamp. The operator deletes the bucket and removes its finalizer; the object disappears and the garbage collector removes the owned children.', flows: [{ from: 'op', to: 'ext', label: 'delete bucket' }, { from: 'gc', to: 'sts', label: 'cascade delete' }] },
  ],
});

registerDiagram({
  id: 'k8s-helm-release',
  roadmap: 'kubernetes', module: 9, topic: 'Helm: Charts, Values, Templating & Releases',
  kind: 'sequence',
  title: 'helm upgrade: render, hook, apply, wait, record (and roll back)',
  desc: 'Helm is a client: it renders templates locally, applies the result through the API server and stores every revision as a Secret. Press Play to follow one upgrade that succeeds and one that is rolled back.',
  actors: [
    { id: 'cli', label: 'helm CLI', sub: 'you or CI', icon: '🧑‍💻', color: 'gray', info: 'All the logic runs here: values merging, template rendering, diffing, hooks, waiting. There is no server-side Helm component since Helm 3.' },
    { id: 'store', label: 'Release Secrets', sub: 'sh.helm.release.v1.*', color: 'yellow', info: 'One Secret per revision in the release namespace (labels owner=helm, name, status). It holds the rendered manifest and values, which is what helm history and helm rollback use.' },
    { id: 'api', label: 'kube-apiserver', sub: 'apply + admission', color: 'blue', info: 'Helm 3 sends three-way strategic merge patches; Helm 4 uses server-side apply. Admission policies see Helm objects like any others.' },
    { id: 'job', label: 'Hook Job', sub: 'pre-upgrade: migrate', color: 'purple', info: 'Resources annotated helm.sh/hook run at fixed points (pre-install, pre-upgrade, post-upgrade…). Helm waits for hook Jobs to complete and fails the release if they fail.' },
    { id: 'wl', label: 'Deployment', sub: 'Pods of the release', color: 'green', info: 'The workload objects from the chart templates. With --wait, Helm polls them until they are ready or the timeout expires.' },
  ],
  steps: [
    { section: 'Render locally' },
    { from: 'cli', to: 'cli', label: 'render + validate', caption: 'Values are merged (chart defaults < parent chart < -f files < --set), checked against values.schema.json and rendered with Go templates. Nothing has been sent yet: helm template shows this output.' },
    { from: 'cli', to: 'store', label: 'read last release', caption: 'Helm loads the latest deployed revision (rev 7). Its stored manifest is the "old" side of the diff, so Helm knows what to change and what to delete.' },
    { from: 'cli', to: 'store', label: 'rev 8: pending', caption: 'It writes revision 8 with status pending-upgrade. A second upgrade now fails with "another operation is in progress"; a CI job killed here leaves the release stuck in pending.' },
    { section: 'Hooks, then apply' },
    { from: 'cli', to: 'job', label: 'create pre-upgrade hook Job', caption: 'Hook resources run first, for example a database migration Job. Helm blocks until it completes; a failed hook fails the upgrade before any workload changes.' },
    { from: 'job', to: 'cli', label: 'Job complete', reply: true, caption: 'Migration done. Hooks are not part of the release manifest, so delete policies (hook-delete-policy) decide when the Job is cleaned up.' },
    { from: 'cli', to: 'api', label: 'apply rendered manifests', caption: 'Helm patches changed objects, creates new ones and deletes objects that disappeared from the chart. CRDs in crds/ are installed once and never upgraded by Helm.' },
    { from: 'api', to: 'wl', label: 'new ReplicaSet, rollout', caption: 'The Deployment controller starts a normal rolling update. Helm itself does not roll Pods; it only changed the desired state.' },
    { from: 'cli', to: 'wl', label: '--wait: poll until Ready', caption: 'With --wait Helm polls Deployments, StatefulSets and Jobs until they are ready or --timeout expires. Without it, Helm reports success as soon as the API accepted the objects.' },
    { from: 'cli', to: 'store', label: 'rev 8: deployed', caption: 'Success: revision 8 is deployed and 7 becomes superseded. --history-max limits how many revision Secrets are kept.' },
    { section: 'A failed upgrade' },
    { from: 'wl', to: 'cli', label: 'timeout: Pods not Ready', reply: true, caption: 'Next upgrade (rev 9) ships a bad image: Pods never become Ready and --wait times out.' },
    { from: 'cli', to: 'store', label: 'rev 9: failed', caption: 'The revision is marked failed. With --rollback-on-failure (Helm 4; --atomic in Helm 3) Helm rolls back automatically; otherwise you run helm rollback.' },
    { from: 'cli', to: 'api', label: 'reapply manifests of rev 8', caption: 'A rollback is a new revision with the old content: Helm applies rev 8 manifests again and the Deployment rolls back to the previous template.' },
    { from: 'cli', to: 'store', label: 'rev 10 = rev 8', caption: 'History stays append-only: rev 10 is deployed with rev 8 content, and helm history shows the whole story for the post-mortem.' },
  ],
});

registerDiagram({
  id: 'k8s-mesh-sidecar',
  roadmap: 'kubernetes', module: 10, topic: 'Service Mesh Primer: Istio & Linkerd',
  kind: 'graph',
  title: 'Service mesh request path: app → sidecar → mTLS → sidecar → app',
  desc: 'With a sidecar mesh, every request crosses two proxies that add mTLS identity, per-request load balancing, retries and telemetry without code changes. Press Play to follow one call from web to payments.',
  groups: [
    { id: 'pa', label: 'Pod web (sa: web)', x: 0, y: 1, w: 2, h: 1, color: 'green' },
    { id: 'pb', label: 'Pod payments (sa: payments)', x: 4, y: 1, w: 2, h: 1, color: 'green' },
    { id: 'cp', label: 'mesh control plane', x: 2, y: 3, w: 2, h: 1, color: 'blue' },
  ],
  nodes: [
    { id: 'appA', label: 'web app', sub: 'GET payments:8080', x: 0, y: 1, color: 'yellow', info: 'Plain HTTP to the Service name. The app knows nothing about TLS, retries or the mesh; it should still propagate trace headers so spans join into one trace.' },
    { id: 'pxA', label: 'sidecar proxy', sub: 'Envoy or Linkerd', x: 1, y: 1, color: 'purple', info: 'Injected by a mutating webhook (as a native sidecar on recent versions). iptables rules set up by an init container or the mesh CNI redirect all outbound and inbound traffic of the Pod through it.' },
    { id: 'pxB', label: 'sidecar proxy', sub: 'authz + TLS end', x: 4, y: 1, color: 'purple', info: 'Terminates mTLS, checks the caller identity against authorization policies (only sa web may call POST /charge), records metrics, then forwards to the app on localhost.' },
    { id: 'appB', label: 'payments app', sub: 'listens :8080', x: 5, y: 1, color: 'yellow', info: 'Receives plain HTTP from its own sidecar over localhost.' },
    { id: 'istiod', label: 'istiod', sub: 'xDS config + certificates', x: 2, y: 3, w: 2, color: 'blue', info: 'Pushes routing, endpoints and policy to every proxy over xDS, and acts as a CA issuing short-lived SPIFFE certificates (spiffe://cluster.local/ns/shop/sa/web) bound to ServiceAccounts.' },
    { id: 'tel', label: 'Prometheus + traces', sub: 'golden metrics, spans', x: 2, y: 0, w: 2, shape: 'db', color: 'teal', info: 'Both proxies report request rate, error rate and latency per source and destination, plus trace spans, for every hop, uniformly across languages.' },
  ],
  edges: [
    { from: 'appA', to: 'pxA' },
    { from: 'pxA', to: 'pxB', label: 'mTLS (SPIFFE IDs)' },
    { from: 'pxB', to: 'appB' },
    { from: 'istiod', to: 'pxA', label: 'xDS, cert' },
    { from: 'istiod', to: 'pxB', label: 'xDS, cert' },
    { from: 'pxA', to: 'tel' },
    { from: 'pxB', to: 'tel' },
  ],
  steps: [
    { caption: 'At Pod creation a mutating webhook injected a proxy into each Pod, and iptables rules (init container or mesh CNI) redirect all its traffic through that proxy. The application image is unchanged.', active: ['pa', 'pb', 'pxA', 'pxB'] },
    { caption: 'The control plane pushes routes, endpoints and policies to every proxy over xDS, and issues each one a short-lived certificate whose SPIFFE ID is derived from the Pod ServiceAccount.', flows: [{ from: 'istiod', to: 'pxA', label: 'config + cert' }, { from: 'istiod', to: 'pxB', label: 'config + cert' }] },
    { caption: 'web calls http://payments:8080 in plain HTTP. The connection never leaves the Pod directly: iptables redirects it to the local sidecar.', flows: [{ from: 'appA', to: 'pxA', label: 'GET /charge' }] },
    { caption: 'The client proxy applies L7 policy: timeout, retry budget, and picks a payments endpoint per request, which also fixes gRPC load balancing. It opens mutual TLS to the server proxy.', flows: [{ from: 'pxA', to: 'pxB', label: 'mTLS request' }] },
    { caption: 'The server proxy verifies the client certificate (identity: sa web), checks the authorization policy, terminates TLS and hands the request to payments over localhost.', flows: [{ from: 'pxB', to: 'appB', label: 'plain HTTP' }] },
    { caption: 'The response goes back the same way. Both proxies emit golden metrics and spans for the hop, so you get uniform telemetry for every service without touching its code.', flows: [{ from: 'pxB', to: 'pxA', label: '200 OK' }, { from: 'pxA', to: 'tel', label: 'metrics, span' }, { from: 'pxB', to: 'tel', label: 'metrics, span' }] },
    { caption: 'A payments replica fails with 503: the client proxy retries once on another endpoint within the retry budget. Unbounded retries at every hop multiply load during an outage: retry storms.', flows: [{ from: 'pxB', to: 'pxA', label: '503', color: 'red' }, { from: 'pxA', to: 'pxB', label: 'retry other Pod' }] },
    { caption: 'The cost: two extra proxies per hop (latency, CPU and memory in every Pod) and proxy upgrades that need Pod restarts. Istio ambient mode moves L4 mTLS to a per-node ztunnel and L7 to optional waypoint proxies.', active: ['pxA', 'pxB', 'istiod'] },
  ],
});
